insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 1, 'Under PIA s.92(4), by when must the holder of an oil mining lease conclude its conversion contract?', '["By the later of 18 months from the effective date and the lease''s own expiry date", "By the earlier of 18 months from the effective date and the expiry date of that oil mining lease", "On one fixed date for every holder, 18 months from commencement, whatever the expiry", "At any time while the lease runs, since s.92(1) makes conversion voluntary"]'::jsonb, 1, 'S.92(4) sets the conversion date as "the earlier of: (a) 18 months from the effective date ; and (b) the expiration date of the oil mining lease". The earlier limb governs, so the later limb is wrong; the second limb reads each lease''s own expiry, so the date is not the same for every holder; and voluntary conversion still has this deadline.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 2, 'A holder lets the conversion date pass without signing. What does PIA s.92(6) say applies to its lease?', '["It becomes a petroleum mining lease automatically, on the 30 percent class of s.267(a) for producing areas", "Every area of it is relinquished under s.93(4), as the holder selected none", "Its producing areas move to the 15 percent class of s.267(b) until it signs", "The terms and conditions that applied to the licence or lease before the Act''s effective date continue"]'::jsonb, 3, 'S.92(6): a holder who "does not enter into a conversion contract prior to the conversion date" keeps "the terms and conditions applicable to the oil prospecting licence or oil mining lease prior to the effective date of this Act". No automatic conversion, no relinquishment and no s.267 class follows; relinquishment in s.93(4) is about areas a converting holder leaves unselected.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 3, 'On conversion of an oil mining lease, which areas does PIA s.93(6)(a) turn into a petroleum prospecting licence?', '["Areas the holder designates under s.93(1)(a), (b), (c) or (2), with fiscal terms under s.267(b)", "Development and production areas under s.93(1)(d) and (e), with fiscal terms under s.267(a)", "Unselected areas, which the Commission regrants to the holder as a prospecting licence", "Every area of the lease, since conversion turns an oil mining lease into one prospecting licence"]'::jsonb, 0, 'S.93(6)(a) converts areas "designated by a holder under subsection (1) (a), (b), (c) or (2) into a petroleum prospecting licence", "with fiscal terms as applicable under section 267 (b)". Development and production areas go to petroleum mining leases under s.93(6)(b) and s.267(a); unselected areas are relinquished under s.93(4); so the lease splits and never becomes one licence.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 4, 'A converting holder''s selection under s.93(1) covers less than 40% of its oil mining lease. What does PIA s.93(2) allow it to do?', '["Nothing more: 40% is the least a conversion may keep, so the holder must relinquish the whole lease", "Add further areas to its petroleum mining leases on the 30 percent class until the 40% is reached", "Select further areas of the oil mining lease for conversion to a petroleum prospecting licence", "Pay the Commission a fee for the shortfall below 40% before the conversion contract is signed"]'::jsonb, 2, 'S.93(2): where the acreage selected under subsection (1) "is less than 40% of the area", "the holder may select additional areas covered by the oil mining lease for conversion to a petroleum prospecting licence". The top-up goes to a prospecting licence, which is the s.267(b) class; the text sets no fee and does not force relinquishment of the whole lease.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 5, 'Ekene Alpha (synthetic; shallow water, converted, 2026 to 2032) is rerun with pia_license_type "PPL". Which provision totals move, changed run less base?', '["Royalties and hydrocarbon tax together, since the licence type also sets which royalty tranches apply", "Hydrocarbon tax and companies income tax, by -102385291.793528 each, since both charge 30 percent", "Hydrocarbon tax alone, by -102385291.793528, with the take moving by -12.247203", "None of the totals, as a prospecting licence shares the 30 percent class of s.267(a) with a mining lease"]'::jsonb, 2, 'The one-change row for a prospecting licence prints royalties 0.000000, hydrocarbon tax -102385291.793528, companies income tax 0.000000 and take -12.247203. The licence type reaches only the hydrocarbon tax class: a prospecting licence is the 15 percent class of s.267(b) (rate 0.150000), and companies income tax does not deduct the hydrocarbon tax, so it stays at 0.000000.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 6, 'Rerun as a new lease at a stated rate of 30, Ekene Alpha''s hydrocarbon tax changes by -24691339.200000 although the rate is the same 30 percent. What moves it?', '["The larger production allowance a new lease earns under the Sixth Schedule para 1(2)", "A lower royalty on new leases, which leaves less royalty to deduct in the hydrocarbon tax base", "Its class under the Nigeria Tax Act 2025, 15 percent for any new lease", "The cost price ratio, which binds converted leases only"]'::jsonb, 0, 'The course reads the new-lease rows this way: a new lease moves the hydrocarbon tax through the larger new-lease production allowance and through the rate it states. At a stated 30 the rate matches the converted class, so the allowance is what acts. Royalties move by 0.000000 on that row, the stated rate returns 0.300000 under either framework, and the cost price ratio reads no lease status.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 7, 'How should a report quote Ekene Alpha''s hydrocarbon tax if Alpha were a lease granted out of new acreage?', '["As a fall of -114730961.393528, because new acreage onshore and in shallow water is the 15 percent class", "As a fall of -24691339.200000, because every petroleum mining lease is the 30 percent class of s.267(a)", "At the engine''s default rate of 30, with the default named in a note in kpis.pia_notes", "With its stated rate, 15 or 30, because PIA s.267 does not say which one applies to such a lease"]'::jsonb, 3, 'The new-lease rate onshore and in shallow water is an open reading: s.267 (NTA s.72) gives 30 percent to leases selected under s.93(6)(b) and (7)(b) and 15 percent to onshore and shallow water, and does not say which applies to a lease granted out of new acreage. The engine keeps no default. The two rows, -114730961.393528 at a stated 15 and -24691339.200000 at a stated 30, are shown together and neither is the law.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 8, 'A new-acreage onshore lease is run with pia_new_pml_hct_rate_pct left unset. What does the engine return?', '["It runs at 30 percent, the s.267(a) class, with a note in kpis.pia_notes naming 30 as the default it chose for a lease out of new acreage", "A refusal that opens \"A new-acreage petroleum mining lease onshore or in shallow water needs pia_new_pml_hct_rate_pct set to 15 or 30; got null.\"", "The ledger at 15 percent, the s.267(b) class for onshore and shallow water, printed with no note and no mention of the rate it chose", "Hydrocarbon tax of 0.000000 in every year until a rate is stated, as deep offshore pays in a year under the Act alone"]'::jsonb, 1, 'That is the engine''s own refusal, and it goes on to say the rate is "a stated user choice with no default". A value the texts leave open is a stated input and a run without it is refused, so neither 15 nor 30 is filled in silently. A note in kpis.pia_notes accompanies a result, and a refusal returns no result at all.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 9, 'Which terms does the engine accept for a producing marginal field in shallow water that converted under PIA s.94(1)?', '["pia_terrain \"marginal_field\", the category the Act''s royalty table names beside onshore fields", "Terrain left blank and the field''s water depth in metres, which the engine reads to set the terrain", "Onshore as the terrain, since a marginal field in shallow water is entered as onshore acreage", "pia_terrain \"shallow_water\" with pia_marginal_field_pre_2021 set to true"]'::jsonb, 3, 'The engine''s refusal of "marginal_field" says a marginal field is onshore or in shallow water and names the flag pia_marginal_field_pre_2021 for a producing marginal field converted under s.94(1). The engine never reads the water depth; the terrain string decides. "onshore" would misstate a shallow water field''s terrain and its tranches above 10,000 bopd.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 10, 'On ekene_marginal_shallow_flag (shallow water, 2026, daily rate 20000.000000 bopd), which pair of rates does the engine return?', '["Liquids royalty rate 0.093750 and hydrocarbon tax rate 0.150000", "A royalty rate of 0.050000, the old flat rate kept by s.94(1), with hydrocarbon tax at 0.150000", "Royalty 0.093750 with hydrocarbon tax at 0.300000, the converted-lease class of s.267(a)", "Onshore tranche royalty of 0.106250 at 20,000 bopd, with hydrocarbon tax at 0.150000"]'::jsonb, 0, 'The course prints the case: daily rate 20000.000000 bopd, liquids royalty rate 0.093750, and a hydrocarbon tax rate of 0.150000 for the flagged field. The royalty follows the shallow water tranches (0.093750 at 20000 bopd); 0.106250 is the onshore rate at that volume. The flag gives the 15 percent class, so 0.300000 ignores it, and the engine models no original royalty rate.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 11, 'PIA s.94(1) lets a producing marginal field keep its original royalty rates and farm-out agreements. Which part of that section does the engine compute?', '["The original royalty rates and farm-out terms, read from the lease terms the learner states for the field", "Only the 15 percent hydrocarbon tax rate, through the stated flag; the rest stays concept-only", "The 18-month deadline, refusing a flagged field that converted late", "Nothing: the flag only adds a note to kpis.pia_notes"]'::jsonb, 1, 'The provision map records s.94(1) as "the 15 percent rate is computed (the stated flag); the rest is concept-only". The engine carries no original royalty rates or farm-out agreements and no conversion date, and the flag does change a figure: it gives the rate 0.150000 where a converted lease pays 0.300000.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 12, 'Under the Nigeria Tax Act 2025 (Official Gazette No. 117, Vol. 112, 26 June 2025), what tax does an oil mining lease that never converted pay, as the course reads the texts?', '["Hydrocarbon tax at 30 percent under NTA s.72(a), because s.196(h) repealed the Petroleum Profits Tax Act", "No petroleum tax until the lease expires, because NTA s.87(1) keeps it outside the hydrocarbon tax Part", "Petroleum profits tax under the Nigeria Tax Act''s own Part II, which s.90(1) applies to leases yet to convert", "Petroleum profits tax under the Petroleum Profits Tax Act 2004, which the Nigeria Tax Act leaves in force"]'::jsonb, 2, 'The Nigeria Tax Act repeals the Petroleum Profits Tax Act (s.196(h)) and carries petroleum profits tax in a Part of its own, whose s.90(1) applies it to "oil prospecting licences and oil mining petroleum leases that are yet to convert". S.87(1) keeps such holders outside the hydrocarbon tax Part, which is why s.72 does not reach them. The engine models none of this: it is concept-only.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 13, 'What cost limits does the PIA Seventh Schedule para 14 set for production sharing contracts?', '["70% for a contract on new acreage and 60% for one subject to a conversion contract", "60% for a contract on new acreage and 70% for one that came in through a conversion contract", "65% for every contract, the cost price ratio limit that the Sixth Schedule sets for hydrocarbon tax", "No limit under a conversion contract, 70% on new acreage"]'::jsonb, 0, 'Para 14(4): "For new acreage any production sharing contract shall have a cost limit of 70% based on total oil production". Para 14(9): "For a production sharing contract subject to a conversion contract under this Act, the cost limit shall be 60%." The 65 percent figure belongs to the hydrocarbon tax cost price ratio. Production sharing under the Act is concept-only in this course.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 14, 'Para 14(4)(d) of the Seventh Schedule prints "over 250 million barrels up to and including 750 million barrels: 25%". How does the course treat the 250?', '["Read as the law, so a field between 250 and 350 million barrels owes the government its 25% profit oil share", "Proof that band (c) should close at 250 million barrels, which the course then corrects in its table", "A figure the engine''s profit oil line applies and grades", "As a misprint where the scale''s own steps need 350, quoted as printed with the error named"]'::jsonb, 3, 'The course lists this among the misprints it quotes as printed: para 14(4)(d) prints "over 250 million barrels" where the scale''s own steps need 350, since band (c) runs "over 100 million barrels and up to and including 350 million barrels". The engine computes no production sharing contract, so nothing here is graded.'),
  ('pia', 'advanced', 'module', 'm01-conversion-and-the-legacy-terms', 15, 'How does the engine carry the outcome of conversion under PIA ss.92 and 93?', '["Modelling each conversion contract from the date s.92(4) sets", "As a stated lease status, \"converted\" or \"new\", with conversion itself taught as concept-only", "Reading licence type \"OML\" and treating it as a mining lease from 2026", "Splitting one ledger into lease and licence areas under s.93(2)"]'::jsonb, 1, 'Voluntary conversion is concept-only: the engine takes the lease status as a stated input and models converted and new-acreage terms only. Any other status is refused in the engine''s words, "pia_lease_status must be "converted" or "new"; got "renewed".", and a licence type from before the Act is refused too: "pia_license_type must be "PML" or "PPL"; got "OML"."'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 1, 'Which list matches what NTA s.197(1)(a) to (d) deletes from the Petroleum Industry Act 2021?', '["Only Chapter Four Parts I to X, with every Schedule kept in the Act for the Nigeria Tax Act to cite", "The whole Seventh Schedule with the Fifth and Sixth, leaving Chapter Four''s hydrocarbon tax Part in place", "Chapter Four Parts I to X, the Fifth and Sixth Schedules, Seventh Schedule paras 6, 9, 10, 11 and 12, and para 14 (6)", "Host communities in Chapter Three, together with the cost price ratio of the Sixth Schedule"]'::jsonb, 2, 'S.197(1) reads: "(a) Part I - X of Chapter Four; (b) the Fifth and Sixth Schedules; (c) paragraphs 6, 9, 10, 11 and 12, of the Seventh Schedule; and (d) paragraph 14 (6) of Part IV of the Seventh Schedule." The Schedules go too, Chapter Four''s Parts go with them, and the Seventh Schedule loses only the listed paragraphs. Chapter Three is not on the list.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 2, 'NTA s.197(1)(a) deletes Parts I to X of Chapter Four of the Petroleum Industry Act 2021. What is Chapter Four?', '["The Act''s fiscal framework: Part I sets its objectives and administration and Part II is the hydrocarbon tax", "Conversion, with ss.92 to 94 and the rules on relinquishing the acreage a holder leaves unselected under s.93(4)", "Host communities, whose trust contribution under s.240(2) is 3 percent of opex", "Royalty: the terrain tranches and the royalty by price with its benchmarks"]'::jsonb, 0, 'The Act''s arrangement of sections reads "CHAPTER 4: PETROLEUM INDUSTRY FISCAL FRAMEWORK PART I: OBJECTIVES AND ADMINISTRATION 258. Objectives. 259. Administration. PART II: HYDROCARBON TAX 260. Application of this Part." So Chapter 4 opens at s.258, after the conversion sections and after s.240; the host communities trusts sit under Chapter 3, and the royalty tranches are in the Seventh Schedule.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 3, 'NTA s.72 and PIA s.267 print the same 30 and 15 percent classes. How does the course relate the two sections?', '["Amendment in place: s.72 amends s.267, so both stay in force side by side and a ledger cites whichever of the two is later", "S.197(1)(a) deletes the Act''s fiscal Parts, and the Nigeria Tax Act re-enacts the same provisions in its own sections", "Deep offshore under s.267 and onshore and shallow water under s.72, side by side", "Only new leases fall under s.72, and s.267 keeps governing converted leases until they expire"]'::jsonb, 1, 'The course reads it so: s.197(1)(a) deletes Parts I to X of Chapter Four, and the same provisions are re-enacted in the Nigeria Tax Act, which is why the NTA sections cited beside the PIA sections (s.65 beside s.260, s.72 beside s.267, s.68 beside s.263) say the same things. Neither s.267 nor s.72 prints a deep offshore rate, and neither splits converted from new leases.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 4, 'Under the engine''s default override "auto", which years does it read as years under the Nigeria Tax Act 2025?', '["Every year after the gazette date of 26 June 2025, so that 2025 is split into two parts on one row", "Every year of a ledger that starts in 2026 or later; a ledger that starts earlier stays on the Act alone", "2025 and every later year, the year the Act was gazetted", "2026 and every later year, read row by row, so one ledger can cross the switch"]'::jsonb, 3, 'Under "auto" a year before 2026 is "pia_only" and 2026 and every later year is "nta_2025", read row by row, so one ledger can cross the switch; a crossing ledger reports kpis.fiscal_framework "pia_only_then_nta_2025". The engine exports NTA_FIRST_YEAR as 2026 and splits no year. The 26 June 2025 date is the gazette date, and 2025 reads "pia_only".'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 5, 'With pia_under_nta_2025_override set to "force_nta", how does the engine read the year 2023?', '["As \"nta_2025\": force_nta puts every year of the ledger on the Nigeria Tax Act 2025", "\"pia_only\", since an override reaches only 2026 onward and leaves earlier years on the Act alone", "Refused, since 2023 is before 2026", "\"pia_only_then_nta_2025\", the value the engine gives a year that sits before the switch"]'::jsonb, 0, 'The framework table prints 2023 as "pia_only" under auto and force_pia and "nta_2025" under force_nta: "force_pia" and "force_nta" put every year on one framework. "pia_only_then_nta_2025" is the value of kpis.fiscal_framework for a whole ledger that crosses under auto and names no single year. No year is refused for its date.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 6, 'A learner types "nta" as the value of pia_under_nta_2025_override. What does the engine do?', '["Runs the ledger as force_nta and prints a note that \"nta\" was read as shorthand for that override", "Falls back to the default \"auto\" for an unknown value and runs the ledger with no note at all", "It refuses: \"pia_under_nta_2025_override must be \"auto\", \"force_pia\" or \"force_nta\"; got \"nta\".\"", "Refuses with a message naming NTA_FIRST_YEAR 2026 as the only year that an override can move"]'::jsonb, 2, 'That is the engine''s refusal, verbatim: the override takes exactly three values and anything else is a thrown error. A refusal returns no ledger, so there is no shorthand reading and no silent fallback to auto, and the message names the three accepted values, with no mention of NTA_FIRST_YEAR.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 7, 'On ekene_onshore_across_2026 (synthetic, onshore, converted, 2024 to 2028), what does the 2026 row carry on the education tax and levy lines?', '["Education tax 4920525.461957 and levy 0.000000, the education tax running on to the end of the lease", "4152684.167129 of TET beside a levy of 4920525.461957, both charged in the first year under the new Act", "Nothing on either line, the levy first charged in the second year under the Nigeria Tax Act 2025", "TET 0.000000 and a development levy of 4920525.461957"]'::jsonb, 3, '2026 is the first "nta_2025" row of this ledger. Its education tax line reads 0.000000, since NTA s.197(5) deletes the sections behind that tax, and its levy line reads 4920525.461957. The figure 4152684.167129 sits on the 2025 row, a "pia_only" year.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 8, 'On what base does the engine charge the development levy of NTA s.59(1)?', '["Hydrocarbon tax assessable profit, at 4 percent, charged beside the income tax base every year", "The companies income tax assessable profit, in years under the Nigeria Tax Act 2025 only", "Gross revenue less every royalty, at 4 percent, in every year of the ledger whatever its framework", "The companies income tax charged, as a 4 percent surcharge"]'::jsonb, 1, 'The instruments table gives the levy''s base as the companies income tax assessable profit in years under the Nigeria Tax Act 2025, and the framework table gives it as none in a year under the Act alone. NTA s.59(4) keeps it off profits computed for the hydrocarbon tax, and the levy reads a profit figure, so gross revenue and the tax charged are both the wrong base.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 9, 'Which statement matches the tertiary education tax rates the engine applies by year?', '["3 percent from 2023, applied to the whole of 2023, and 2.5 percent before, a rate resting on a secondary source", "3 percent from 1 May 2023 only, so 2023 is charged at two rates split by the months either side", "2.5 percent in every year under the Act alone, as the Finance Act 2023 scan could not be relied on", "4 percent from 2023, the same rate the development levy charges on the same base from 2026"]'::jsonb, 0, 'The rate table prints 2.500000 for 2021 and 2022 and 3.000000 for 2023 to 2025. The Finance Act 2023 raised the rate with effect from 1 May 2023 (s.26, s.30); the annual model applies 3 percent to the whole of 2023, and the 2.5 percent before rests on a secondary source. The development levy''s 4 percent is a different instrument.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 10, 'Ekene Alpha is rerun with every year forced to the Act alone. What happens to its education tax and levy totals?', '["A straight swap at par: TET changes by 35714217.371697 and the levy by -35714217.371697", "Both move by 0.000000, since Alpha has no year before 2026 for the Act alone to govern in the first place", "Only the education tax moves, by 26785663.028773, the levy staying in the years the new Act reached", "TET changes by 26785663.028773 and the levy by -35714217.371697"]'::jsonb, 3, 'The one-change row prints TET 26785663.028773 and levy -35714217.371697. Forcing the Act alone swaps the development levy for the tertiary education tax, and the two are charged at different rates on the same companies income tax assessable profit, 3 percent against 4 percent, so the two lines do not trade at par. A forced run puts every year on one framework, whatever its date.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 11, 'The 2024 spend on ekene_onshore_across_2026 reaches its fifth year of life in 2028. What fraction does 2028 claim?', '["19 percent, since the spend was made in 2024 under the Act alone and keeps that year''s schedule", "20 percent for the year plus the 1 percent the Act alone retained, released at the switch", "20 percent, since 2028 is a year under the Nigeria Tax Act 2025 and the law of each year decides", "19 percent, with the other 1 percent recorded as a notional amount that the new Act then lets the company claim"]'::jsonb, 2, 'The capital allowance is read by the law of the year of assessment: year 4 of life is 0.190000 under the Act alone and 0.200000 under the Nigeria Tax Act 2025, and the course checks that the 2024 spend claims 20 percent in 2028. NTA First Schedule Part II para 4(2) says the 1 percent is "a notional amount" that "shall not increase or reduce the amount of capital allowance claimable".'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 12, 'On ekene_force_pia_2027 every year is forced to the Act alone. What is the fifth-year capital allowance of the 2027 spend, claimed in 2031?', '["0.000000, since a spend''s fifth year of life claims nothing under either law and the claim ends in 2030", "11400000.000000, the 19 percent fifth-year fraction of a year under the Act alone", "18000000.000000, the onshore ledger''s 2028 claim", "11400000.000000 plus the 1 percent retained under the Fifth Schedule, which that ledger releases in 2031"]'::jsonb, 1, 'The forced ledger prints the fifth-year allowance of the 2027 spend, in 2031, as 11400000.000000. Year 4 of life (0 is the year of spend) is the fifth year and claims 0.190000 under the Act alone; year 5 is the one that claims 0.000000. The 1 percent of para 5(2) is retained until disposal and never claimed in the ledger. 18000000.000000 belongs to a different case.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 13, 'On ekene_cpr_binding_forfeiture the two thirds restriction binds in 2024 and 2025. What happens to the carried capital allowance in 2026?', '["Two thirds of the assessable profit is claimed again, with the rest carried on to a later year", "It is forfeited at the switch, as the cost price ratio carry is forfeited when a ledger ends", "None of it is claimed: the 2026 assessable profit of -457065.217391 leaves no room for a claim", "It is claimed in full, the 2026 claim reaching 65038687.352504, as 2026 is a year under the Nigeria Tax Act 2025"]'::jsonb, 3, 'The companies income tax rows print the claim as 15999597.939440 in 2024 and 8961714.708056 in 2025, two thirds of each assessable profit, and 65038687.352504 in 2026. A year under the Nigeria Tax Act 2025 carries no restriction and a carried amount is claimed in full, even against an assessable profit of -457065.217391; forfeiture belongs to the hydrocarbon tax cost price ratio.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 14, 'When does the engine print the note "Nigeria Tax Act 2025 figures follow Official Gazette No. 117, Vol. 112, of 26 June 2025." in kpis.pia_notes?', '["Whenever the ledger holds a year under the Nigeria Tax Act 2025", "On every PIA ledger, as it prints the note on the daily rate the royalty tranches read", "Only when pia_under_nta_2025_override is \"force_nta\", which puts every year on the new Act", "Only on a deep offshore ledger, whose stated reading rests on the June 2025 wording of s.65(1)"]'::jsonb, 0, 'The note table gives ntaVersion''s condition as "a year under the Nigeria Tax Act 2025". A ledger under auto that reaches 2026 carries it without any override, a ledger wholly before 2026 or forced to the Act alone carries none, and nothing in its condition is about terrain. The daily-rate note is the one printed on every PIA ledger.'),
  ('pia', 'advanced', 'module', 'm02-what-the-tax-act-moved', 15, 'What does the course know about the text of the Nigeria Tax Act 2025 that it quotes?', '["The re-gazetted Certified True Copy of December 2025, which replaces the June text entirely", "Its text came from the State House statement, which carries the Act in full with its 1 January 2026 date", "It read the June 2025 gazette on 2026-09-26; re-gazetting was ordered in December 2025 and no Certified True Copy was read", "June 2025 gazette text, whose commencement note sets the effective date of 1 January 2026"]'::jsonb, 2, 'The editions table gives Official Gazette No. 117, Vol. 112, Lagos, 26 June 2025, effective 1 January 2026 by the State House statement, with re-gazetting ordered in December 2025 and no Certified True Copy read, all read on 2026-09-26. The statement is a secondary source for the date, and the gazette''s commencement note prints "[ 26th June, 2025 ]".'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 1, 'The Ekene deep offshore lease (synthetic; new acreage, 60,000 bopd) is run for 2026 under each stated reading. Which set of hydrocarbon tax figures does the engine return?', '["0.000000 under every reading, since PIA s.260(3) still keeps deep offshore out of the tax in 2026", "aggressive_pml_30 202414673.913043 and custom 20 303622010.869565", "303622010.869565 under every reading", "conservative_zero 0.000000; aggressive_pml_30 303622010.869565; custom 20 202414673.913043"]'::jsonb, 3, 'The three-readings table prints 2026 as 0.000000 under conservative_zero, 303622010.869565 under aggressive_pml_30 and 202414673.913043 under a stated custom 20, on an HCT chargeable profit of 1,012,073,369.565217. 2026 is a year under the Nigeria Tax Act 2025, where the rate is a stated reading, so the figures differ by reading and each is quoted with its own.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 2, 'Why does the deep offshore hydrocarbon tax under the Nigeria Tax Act 2025 need a stated reading at all?', '["NTA s.72 prints a deep offshore rate of 30 percent that s.65(4) then withdraws until reclassification", "NTA s.65(1) brings deep offshore into the tax, and s.72 prints rates only for onshore and shallow water", "PIA s.260(3) survives the deletions and still excludes deep offshore in every year from 2026 onward, as it did in 2025", "The Regulations and the Act name different years for the deep offshore rate to begin being charged"]'::jsonb, 1, 'The engine''s refusal gives the reason in its own words: "NTA s.65(1) applies hydrocarbon tax to deep offshore operations but s.72 states rates only for onshore and shallow water, so the rate is a stated user choice with no default." S.65(4) is the frontier exclusion, s.260(3) sits in the Chapter Four Part that s.197(1)(a) deletes, and the base year question belongs to the royalty by price.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 3, 'Which of the three deep offshore readings is the law for a year under the Nigeria Tax Act 2025?', '["The Act does not settle it: the engine takes the reading as a stated input with no default and the course grades none", "aggressive_pml_30, because s.65(1) names deep offshore and s.72(a) is the only 30 percent class in the Act", "conservative_zero, the reading the engine applies by default whenever a ledger states no reading", "custom at 20 percent, the midpoint between the two named readings that the engine prints in its table"]'::jsonb, 0, 'The texts leave this open, and the course teaches all three readings side by side and grades none. The engine keeps no default: a deep offshore year under the new Act with no reading is refused. The custom 20 row is a stated example of the custom reading, and the course names no reading as correct.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 4, 'A deep offshore ledger running into 2026 is given no pia_deep_offshore_hct_interpretation. What does the engine do?', '["Runs under conservative_zero and adds a note to kpis.pia_notes saying which reading it chose", "Only 2025 is run, the ledger stopping at the last year under the Act alone, with a note on why", "It refuses the run, since the rate is a stated user choice with no default", "Charges the 7.5 percent deep offshore royalty rate as the hydrocarbon tax rate for 2026 onward"]'::jsonb, 2, 'The refusal opens "A deep offshore year under the Nigeria Tax Act 2025 needs pia_deep_offshore_hct_interpretation set to "conservative_zero", "aggressive_pml_30" or "custom"" and ends "so the rate is a stated user choice with no default." A refusal is a thrown error, so no partial ledger and no note is returned, and the royalty rate plays no part in the tax rate.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 5, 'The reading is set to "custom" and no custom rate is stated. What comes back?', '["Runs at a custom rate of 20 percent, the figure the course''s own three-readings table uses for it, with a note naming that default", "The refusal \"pia_deep_offshore_hct_interpretation \"custom\" needs pia_deep_offshore_hct_custom_rate_pct as a number from 0 to 100; got null.\"", "Zero percent: the custom reading falls back to conservative_zero when it has no rate, and the ledger prints a note saying so", "A ledger at 30 percent, the custom reading taking the s.72(a) class of converted leases when no figure is written in"]'::jsonb, 1, 'That is the engine''s own message for this input: a custom reading needs its rate stated as a number from 0 to 100. The 20 in the course''s table is a stated example, and the engine fills in no rate from another reading, so a custom reading with no rate is refused.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 6, 'On the Ekene deep offshore lease, which lines does changing the stated reading move?', '["Hydrocarbon tax and companies income tax, since the hydrocarbon tax is deducted in the income tax base", "Royalty and hydrocarbon tax, since the liquids royalty rate of 0.054167 rises under the 30 percent reading", "Every line of the ledger from 2025 on, the stated reading reaching back into the year under the Act alone", "The hydrocarbon tax line and nothing else"]'::jsonb, 3, 'The course checks that the reading moves the hydrocarbon tax line and nothing else: companies income tax is 303622010.869565 in 2026 under every reading, the royalty rate is 0.054167 in every year, and 2025 pays no hydrocarbon tax under any reading. Companies income tax does not deduct the hydrocarbon tax (PIA s.302(5); NTA s.78(3)(a)).'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 7, 'What hydrocarbon tax does the Ekene deep offshore lease pay in 2025, and why?', '["0.000000 under every reading: 2025 is a year under the Act alone, and PIA s.260(3) keeps deep offshore out", "0.000000 under conservative_zero only, with the other two readings charging 2025 at their stated rates", "No figure at all, as the ledger crosses into the new Act and so 2025 needs a stated reading as well", "0.000000 because the 175200000.000000 production allowance leaves the year with no chargeable profit to charge"]'::jsonb, 0, 'The 2025 row reads "pia_only" with an HCT chargeable profit of 795646660.199557 and a hydrocarbon tax of 0.000000 under all three readings. S.260(3): "This Part shall not apply to a frontier acreage until it is reclassified under section 68 (3) of this Act and to deep offshore." The chargeable profit is positive after the allowance, so the allowance does not explain the zero.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 8, 'The deep offshore lease earns a production allowance of 175200000.000000 in 2025 and 0.000000 in 2026 on the same barrels and price. What removes it?', '["Its cap of 500 million barrels, reached during 2025, so that no barrel produced in 2026 sits below it", "A switch to the converted-lease allowance, the lower of 2.50 USD/bbl and 20 percent, from 2026 onward", "The Nigeria Tax Act 2025 re-enacts the new-lease allowance for onshore and shallow water only", "The conservative reading, which zeroes the allowance with the tax"]'::jsonb, 2, 'The course reads the deletion from the two Sixth Schedules: the NTA list ends at (b) shallow water, "the lower of US $8.00 per barrel and 20% of the fiscal oil price, up to a cumulative maximum production of 100" million barrels, and prints no paragraph for deep offshore and frontier. The lease is a new lease, so the converted allowance does not apply, and the three-readings table prints 0.000000 in 2026 under every reading.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 9, 'One million barrels at 75 USD/bbl with no earlier production, in a year under the Nigeria Tax Act 2025. Which lease does the engine give an allowance?', '["New deep offshore lease: 8000000.000000, the lower of 8.00 USD/bbl and 20 percent below the cap", "Frontier, as a new lease: 8000000.000000 on every barrel up to its cap of 500 million barrels", "A new deep offshore lease: 4000000.000000, the rate after the cap applied to every barrel", "A converted shallow water lease: 2500000.000000"]'::jsonb, 3, 'The allowance table prints, in an nta_2025 year at 75 USD/bbl, 2500000.000000 for a converted shallow water lease and 0.000000 for a new deep offshore lease and for a new frontier lease. 8000000.000000 is what the new deep offshore lease earns in a year under the Act alone, and 4000000.000000 is an onshore figure after the cap.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 10, 'On the two NTA decommissioning fund cases (synthetic, shallow water, 2026 to 2028), what is companies income tax in 2026?', '["33069497.282609 with the condition met and 30069497.282609 with it not met, the deduction adding to tax", "30069497.282609 with the escrow condition met and 33069497.282609 with it not met", "30069497.282609 in both runs, the cash leaving either way", "30069497.282609 met and 31569497.282609 not met, the unmet condition moving only the hydrocarbon tax"]'::jsonb, 1, 'The escrow table prints 2026 companies income tax as 30069497.282609 (met) and 33069497.282609 (not met). The contribution of 10000000.000000 goes out in both runs; only the deduction moves, 10000000.000000 met and 0.000000 not met. 31569497.282609 is the hydrocarbon tax with the condition not met, which moves too.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 11, 'What does NTA s.86 require before a decommissioning fund contribution is deductible?', '["The whole fund held in an escrow account the Commission controls, audited each year by the Service before the deduction is allowed", "Payment of 30% of each year''s contribution into the Federation Account before any part of that contribution is deducted", "At least 30% of the fund in an escrow account with a Nigerian bank accredited under criteria of the Central Bank of Nigeria with the Service", "At least 30% of the fund invested in Nigerian government bonds that the Commission has approved, held to maturity"]'::jsonb, 2, 'S.86(a) requires that "the licensee or lessee deposit a minimum of 30% of the" fund with a Nigerian bank in escrow, and s.86(b) that "the Nigerian bank is accredited in accordance with the criteria for accreditation for participation in the management of the fund, determined by the Central Bank of Nigeria in collaboration with the Service." A minimum of 30 percent, a bank and an escrow account are the condition.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 12, 'Why does ekene_sinking_fund_pia_years (2024 and 2025) run with no escrow statement at all?', '["Both years are under the Act alone, where a fund contribution is deductible with no escrow condition", "The engine sets the escrow condition to true by default whenever the terms leave it unstated", "Its contribution of 15000000.000000 is below the size of fund that brings NTA s.86 into play", "The escrow condition reaches the hydrocarbon tax only, and those two years carry none of it"]'::jsonb, 0, 'The engine asks for pia_decom_escrow_condition_met only for a year under the Nigeria Tax Act 2025 with a contribution, and its refusal names that year: "2026 is a year under the Nigeria Tax Act 2025 and carries a decommissioning fund contribution". In a year under the Act alone the contribution is deductible, and the case deducts 15000000.000000 in 2024 and 2025. The engine keeps no default and s.86 sets no fund size.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 13, 'On ekene_min_etr_nta_only (synthetic, shallow water, 2025 and 2026), what does the minimum effective tax top-up line show?', '["35346403.532609 in 2026 at 15, since 15 percent is the statutory rate of s.57(1) and so it binds", "At a stated 15, 0.000000 in both years; at a stated 85, 0.000000 in 2025 and 35346403.532609 in 2026", "Both years at 85 carry 35346403.532609, the top-up paying no attention to the framework of either year", "A refusal at 15, since s.57 tests a company and the engine will not run a project-level test"]'::jsonb, 1, 'The top-up table prints 0.000000 at 15 in both years, and 0.000000 in 2025 and 35346403.532609 in 2026 at the golden input''s stated 85, set high so the top-up shows. The approximation runs in years under the Nigeria Tax Act 2025 only, and 2025 is a year under the Act alone. It is a labelled approximation, reported and never refused.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 14, 'Why does the course never key the engine''s minimum effective tax top-up as the tax a company owes?', '["The 15 percent minimum rate is one of the open readings the texts leave for the user to state", "The top-up applies only to years under the Act alone, and those years are not graded anywhere", "S.57 was withdrawn by the re-gazetting of December 2025", "NTA s.57 tests the company on audited profit, which a project model cannot see"]'::jsonb, 3, 'The engine''s note says so: "the Act tests the company (a member of a multinational group, or turnover of 20 billion naira or more) on audited profit before tax less 5% of depreciation and personnel cost, which a project model cannot see." The course''s open readings are three other questions, the top-up runs only in NTA years, and nothing says the re-gazetting changed s.57.'),
  ('pia', 'advanced', 'module', 'm03-what-the-tax-act-changed', 15, 'Ekene Alpha is run with every year forced to the Act alone. By how much do its royalties move?', '["0.000000: the royalty and royalty by price functions take no framework input", "A small amount, since the NTA restates the tranches with \"bop\" where the Act writes bopd", "-863333.550000, as the Nigeria Tax Act''s Seventh Schedule sets the gas royalty afresh", "By 436533.662718, from new benchmarks in 2026"]'::jsonb, 0, 'The one-change row prints royalties 0.000000 for every year forced to the Act alone. The course states that the engine''s royalty and royalty by price functions take no framework input. The "bop" slip is a misprint the course names, -863333.550000 is the all-gas-in-country row, and 436533.662718 is the hydrocarbon tax on the forced row.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 1, 'At a stated in-country gas share of 40 percent, what gas royalty rate does the engine return?', '["0.040000, in every terrain", "0.040000 onshore and 0.050000 offshore, since the in-country rate is written for land fields", "0.025000, since any gas used in-country takes the whole volume down to the 2.5 percent rate", "0.035000: 40 percent of the gas at 5 percent and the other 60 percent at 2.5 percent"]'::jsonb, 0, 'The gas royalty table prints 0.040000 at a stated 40 in all four terrains: the rate is the share-weighted blend of 2.5 percent on the in-country share and 5 percent on the rest, and every terrain pays the same gas rate. 0.035000 is the rate at a stated 60, the blend turned the wrong way round.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 2, 'Why does the Ekene gas field ekene_nag_gas_in_country_half pay no hydrocarbon tax in any year?', '["Half of its gas is used in-country, and s.302(6) exempts in-country gas from the tax", "It is in shallow water, where gas meets the tax only once it passes 10,000 bopd", "It produces no crude oil or condensate, so its cost price ratio cap is 0 and the tax has nothing to charge", "The greenfield gas credit of NTA s.85 offsets its hydrocarbon tax in full"]'::jsonb, 2, 'The course prints the case with CPR cap 0.000000, HCT chargeable profit 0.000000 and HCT 0.000000 in 2026 to 2028, and says the field has no crude oil or condensate, so there is no hydrocarbon tax; companies income tax is charged on the gas profit (10713000.000000 in 2026). The engine does not compute the s.85 credit, and s.302(6) is about midstream and pipeline incentives.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 3, 'Stating all of Ekene Alpha''s gas as used in-country moves which provision totals?', '["Royalties by -863333.550000 and hydrocarbon tax by 259000.065000, gas royalty sitting in that base", "Royalties alone, by -863333.550000, the smaller gas royalty reaching none of the lines after it", "Nothing at all, since Alpha''s associated gas pays the crude oil tranche rate on its gas", "Royalties by -863333.550000, companies income tax by 259000.065000 and the levy by 34533.342000"]'::jsonb, 3, 'The one-change row prints royalties -863333.550000, hydrocarbon tax 0.000000, companies income tax 259000.065000, levy 34533.342000 and take -0.068159. Gas royalty is not deducted in the hydrocarbon tax base (gas is outside the tax), so that line stays at 0.000000, while the income tax base, which deducts every royalty, grows.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 4, 'Which one-change row on Ekene Alpha moves royalties while the hydrocarbon tax difference stays at 0.000000?', '["Oil at 95 USD/bbl on the Regulations base, which lifts the royalty by price with it", "All gas used in-country", "A prospecting licence under s.267(b), whose class sits on the same crude oil profit", "Every year forced to the Act alone, which swaps the levy for the education tax"]'::jsonb, 1, 'Of these rows only the gas one has a royalty difference (-863333.550000) with a hydrocarbon tax difference of 0.000000. Oil at 95 moves both (43566660.591831 and 72668690.783886), a prospecting licence moves the hydrocarbon tax only, and the forced row moves royalties by 0.000000.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 5, 'What royalty rate do the Petroleum Royalty Regulations 2022 give natural gas liquids produced separately?', '["2.5% when they are used in-country and 5% when exported, as for the gas they come from", "5%, whether the natural gas liquids are used in-country or exported", "The crude oil tranche rate, since natural gas liquids count as condensate for royalty purposes", "7% onshore and 5% offshore, from NTA Part IV"]'::jsonb, 1, 'R.16(4): "The royalty rate of natural gas liquids produced separately, shall be 5% regardless of whether the natural gas liquids are used in-country or exported." For royalty, natural gas liquids count as natural gas (PIA Seventh Schedule para 6), and the 7 and 5 percent rates are for leases under NTA Chapter Three Parts II and III.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 6, 'PIA s.260(2) allocates the costs of associated gas to crude oil. What does the engine do in its place?', '["Enters shared costs in the hydrocarbon tax at the crude-plus-condensate share of gross revenue, since it cannot tell the two gases apart", "Reads a gas tag on each production row, associated or non-associated, and puts every associated gas cost on crude oil as s.260(2) says", "All condensate treated as non-associated gas condensate under s.260(1)(b)(ii), with every barrel of it kept out of the tax", "It charges gas revenue to the hydrocarbon tax at the crude-plus-condensate share of the revenue, so associated gas pays with crude"]'::jsonb, 0, 'The engine''s note: "Opex, HCDT, NDDC, capital allowances and any decommissioning contribution enter the hydrocarbon tax at the crude-plus-condensate share of gross revenue. The Act allocates associated-gas costs to crude oil (s.260(2)) and excludes non-associated gas condensate from the tax (s.260(1)(b)(ii)); the engine cannot tell the two gases apart." Gas revenue stays outside the tax.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 7, 'Ekene Alpha''s liquids share of gross revenue is 0.970075 in every year from 2026 to 2032. What does the engine use it for?', '["Charging that share of gas revenue to the hydrocarbon tax base alongside crude oil", "Scaling the government take to that share of its value before it is reported", "Opex, HCDT, NDDC and the capital allowance enter the hydrocarbon tax at that share", "Setting the cost price ratio cap at that share of the 65 percent limit on revenue"]'::jsonb, 2, 'The liquids share rows are derived as liquids revenue over gross revenue, and the course says the NDDC levy is deducted in the hydrocarbon tax base at the liquids share, as HCDT is, with opex and the capital allowance entering at the same share. Gas revenue is outside the tax, the take is government cash flow over the pre-take value, and the cap is 65 percent of crude oil and condensate revenue.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 8, 'When does the engine print its note on shared costs in kpis.pia_notes?', '["On every PIA ledger, whatever it produces, as it prints the note on the realised price", "Only on a field with gas and no crude oil, such as ekene_nag_gas_in_country_half", "Only when pia_gas_in_country_share_pct is stated above 0 for the ledger", "On a ledger with gas production in some year"]'::jsonb, 3, 'The note table gives sharedCosts'' condition as "a ledger with gas production in some year". Ekene Alpha, which sells associated gas beside its crude, carries it as well as the gas field does, and the in-country share has no part in the condition. The fiscal price note is the one printed on every PIA ledger.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 9, 'Under NTA s.85(1)(a), what credit does a qualifying non-associated gas field in the leanest liquids band earn?', '["The lower of US$1.00 per thousand cubic feet and 30% of the fiscal gas price", "The lower of US$0.50 per thousand cubic feet and 30% of the fiscal gas price", "US$1.00 per thousand cubic feet or 30% of the realised gas price, whichever is higher", "A production allowance of US$1.00 per thousand cubic feet against the tax base"]'::jsonb, 0, 'S.85(1)(a) grants the credit at the "rate of US$1.00 per thousand cubic feet or 30% of the fiscal gas price, whichever is lower;" for gas whose liquids do not exceed 30 barrels per million standard cubic feet. The US$0.50 figure is the middle band of s.85(1)(b), and s.85(2) is the provision that grants an allowance. The credit is concept-only in this course.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 10, 'For how long does the NTA s.85 gas tax credit run, and how long may an unused credit be carried?', '["Three years of sales from first gas production, with an unused credit carried forward for 10 years", "Until 1 January 2029, unused credit lapsing each year", "10 years of sales from first gas production, with an unused credit carried forward without limit", "10 years of sales from first gas production, carried forward at most three years"]'::jsonb, 3, 'S.85(1)(d): the credit "shall apply on Non-Associated Gas sales for 10 years only, beginning from the date of attaining first gas production". S.85(4): "Unrecouped tax credit in one year may be carried forward for a maximum of three years." 1 January 2029 closes the window for first gas, and the carry is capped.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 11, 'A non-associated gas greenfield project first produces commercial gas after 1 January 2029. What kind of relief does NTA s.85(2) grant it, set beside s.85(1)?', '["The same s.85(1) tax credit, its window extended past 1 January 2029 for projects that start late", "A gas production allowance, where s.85(1) grants a gas production tax credit", "No relief of any kind, since s.85 closes to every project on 1 January 2029", "A royalty of 2.5 percent on its gas, the rate para 10(6) sets for gas used in-country"]'::jsonb, 1, 'S.85(2): "In the case of all other Non-Associated Gas Greenfield projects with first commercial gas production after 1 January, 2029, gas production allow- ance shall be granted at US$0.50 per thousand cubic feet or 30% of the fiscal gas price, whichever is lower,". S.85(1)(b) speaks of "a gas production tax credit". Late projects get a relief of a different kind, and the royalty rate is untouched by s.85.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 12, 'How does this course treat the NTA s.85 greenfield gas credit?', '["Computed as a line on the gas field''s ledger, and graded once the credit''s inputs are stated", "Only for fields whose first gas arrives before 1 January 2029 is it computed, on a stated date", "As concept-only: the engine does not model it, and it reads the stated gas price where s.85 names the fiscal gas price", "As part of the gas royalty rate, where it appears as the 2.5 percent rate for gas used in-country"]'::jsonb, 2, 'The engine''s list of what it does not model includes the non-associated gas credit, and its note says "The realised oil and condensate prices stand in for the Commission''s fiscal prices", and it applies the gas price the case states. A concept-only provision is taught from its text and never graded on a number, and the 2.5 percent in-country rate is a royalty rule of para 10(6).'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 13, 'What do PIA s.302(6) and NTA s.80(1) give investors in gas pipelines?', '["Royalty holiday of five years on all gas the pipeline delivers to the domestic market, on top of the in-country royalty rate", "2.5 percent gas royalty on every volume the pipeline carries, whatever its destination", "A tax-free period of five years at the expiration of an earlier tax-free period or certificate", "A credit of US$0.50 per thousand cubic feet on the gas they carry for five years from startup"]'::jsonb, 2, 'S.302(6): "investors in gas pipeline will be granted an additional tax-free period of five years at the expiration of the tax-free period"; NTA s.80(1): "shall be granted a tax-free period of five years at the expiration of the economic" development incentive certificate. Both are company-level reliefs the engine does not compute, and neither is a royalty rule or a credit per unit.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 14, 'What do PIA s.305 and NTA s.88(1) say about stabilisation clauses in contracts made after the Act''s commencement?', '["They do not shield contractors from changes to the listed fiscal provisions, favourable or unfavourable; NTA s.88(1) adds that changes must not discriminate", "Fiscal terms of a converted lease frozen at its conversion date for the life of the lease, whatever later Acts change", "Protection from unfavourable changes only, favourable changes to the listed fiscal provisions passing straight through to the contractor", "They bind only production sharing contracts signed before commencement, leaving every lease and licence outside their reach"]'::jsonb, 0, 'S.305: such clauses "shall not be applicable to the fiscal provisions listed in this section, regardless of whether these changes affect the contractor favorably or unfavorably,". NTA s.88(1) restates it, "provided such changes in fiscal provi- sion are being made in a manner that is not discriminatory to the petroleum industry or the contractor." Stabilisation is concept-only.'),
  ('pia', 'advanced', 'module', 'm04-gas-and-incentives', 15, 'On ekene_nag_gas_in_country_half (2026 to 2028) the flag pia_cit_company_gas_operations is set to true. What can it change?', '["The gas royalty rate, which falls from 0.037500 to 0.025000 for a company in gas operations", "The hydrocarbon tax, which the exemption lifts from 0.000000 to the 30 percent class of s.267(a)", "Companies income tax in 2026, which falls as a restricted and carried capital allowance from earlier years is released in full", "Nothing on this case: it exempts a company from the two thirds restriction, which applies only in years under the Act alone"]'::jsonb, 3, 'The flag exempts a company in upstream or midstream gas operations from the two thirds restriction on the companies income tax capital allowance. The restriction applies in a year under the Act alone and not in a year under the Nigeria Tax Act 2025, and every year of this case is an NTA year. The gas royalty reads only the in-country share.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 1, 'In the wording this course shares with the fiscal course, what is "Government take"?', '["Government cash flow divided by revenue less opex over the project life, capex added back to the contractor side", "Total tax over the companies income tax assessable profit, year by year", "Government cash flow and revenue, both discounted at 10 percent", "Government cash flow divided by revenue less opex less capex over the project life"]'::jsonb, 3, 'The conventions file: "Government cash flow divided by the project''s pre-take net cash flow, which is revenue less opex less capex, over the project life." Adding capex back to the contractor side gives the second metric, "Government share of net revenue". The engine''s take is undiscounted and nominal, and it is a ratio of totals over a life.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 2, 'The engine reports Ekene Alpha''s government take as 66.564877. Which two totals does that figure divide?', '["Hydrocarbon tax plus companies income tax over the pre-take value of 835989167.000000", "Government cash flow of 556475163.954050 over a pre-take value of 835989167.000000", "Government cash flow of 556475163.954050 over revenue less opex", "Total royalties of 79273732.707567 plus every tax, over gross revenue for the life"]'::jsonb, 1, 'The decomposition prints government cash flow (the sum of the seven lines) 556475163.954050 and the pre-take value (revenue less capex less opex) 835989167.000000, and checks that their ratio reproduces the engine''s 66.564877. The two taxes alone leave out royalties, the levy, HCDT and NDDC, and the denominator subtracts capex.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 3, 'Ekene Alpha is rerun at a 50 percent working interest (ekene_alpha_wi_50). What happens to its money lines and its take?', '["Money lines halve except royalty, which the operator pays at field level, so the take rises a little", "The tranches read half the daily rate, so royalty falls by more than half and the take falls with it", "Every money line is half, and the take stays at 66.564877", "Every money line is half, and the take halves too, to the share of the take the partner carries"]'::jsonb, 2, 'The course checks that at 50 percent every money line is half and the take does not move: 66.564877 on both lines, because the tranches and caps are read at field level before the share is taken (PIA s.273(4); NTA s.77(4)). Royalty is a money line and halves with the rest (39636866.353784 against 79273732.707567).'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 4, 'Why is the tertiary education tax line 0.000000 in Ekene Alpha''s decomposition?', '["Every Alpha year, 2026 to 2032, is a year under the Nigeria Tax Act 2025, where the development levy is charged in its place", "Alpha''s companies income tax assessable profit is below the threshold the Finance Act 2023 sets for the tax", "The engine folds the education tax into companies income tax, so it has no line of its own", "The education tax is charged on the hydrocarbon tax base, and Alpha''s liquids share removes it"]'::jsonb, 0, 'Alpha runs 2026 to 2032, every row "nta_2025". The framework table gives the tertiary education tax as none in a year under the Nigeria Tax Act 2025 (NTA s.197(5)) and the development levy as 4 percent of the companies income tax assessable profit; Alpha''s levy is 35714217.371697. The education tax reads the companies income tax assessable profit when it is charged.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 5, 'In Ekene Alpha''s decomposition HCDT is 4320000.000000 against NDDC 9540000.000000. What rule behind HCDT keeps its first year empty?', '["HCDT is 3 percent of the year''s own opex plus capex, and its first year has capex only", "Only once the field''s production passes 10,000 bopd is HCDT charged, which Alpha never does in any year of its ledger", "HCDT is 3 percent of the preceding year''s opex, and Alpha''s first year reads a prior-year opex of 0", "A fixed sum of 720000.000000 a year, which begins in the second year of any ledger"]'::jsonb, 2, 'HCDT is 3 percent of the preceding year''s opex, and the first ledger year reads the stated pia_prior_year_opex_usd (0 if not stated); Alpha''s 2026 HCDT is 0.000000 and every later year 720000.000000. The NDDC levy reads opex plus capex, which is why its 2026 figure is 4320000.000000. Nothing in HCDT reads the daily rate.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 6, 'Moving Ekene Alpha onshore changes every provision total by 0.000000. What does the course read from that?', '["The engine ignores the terrain once a lease has converted, whatever the daily rate", "Onshore royalty is higher, and the hydrocarbon tax falls by exactly the same amount", "Onshore and shallow water pay one terrain rate, 12.5 percent, at every volume", "Every Alpha year is below 10,000 bopd, where onshore and shallow water pay the same rate"]'::jsonb, 3, 'The course reads the row this way: moving Alpha onshore changes no royalty, because every Alpha year is below 10,000 bopd where onshore and shallow water pay the same rate. The terrain rates differ above 10,000 bopd (15 percent onshore, 12.5 percent in shallow water), and a converted lease pays 0.300000 in both terrains.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 7, 'At oil 95 USD/bbl, Ekene Alpha''s royalties change by 43566660.591831 on the Regulations base. What does the Act base give, and how is each figure quoted?', '["41321586.250479, each figure quoted with its base year, since the base year is an open reading", "43566660.591831 on both bases, because the price and the barrels are the same in each run", "41321586.250479, and that figure is the law, since an Act always outranks the regulations made under it", "43566660.591831 plus one more year of escalation, the Act base adding a further 2 percent to the royalty"]'::jsonb, 0, 'The one-change rows print 43566660.591831 on the Regulations base and 41321586.250479 on the Act base. The base year of the royalty by price is one of the three open readings: the Act starts the benchmarks in 2020, the Regulations in 2021, and the course teaches both and grades neither against the other.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 8, 'Why does the same 95 USD/bbl move Alpha''s royalties less on the Act base than on the Regulations base?', '["Condensate is left out of the royalty by price on the Act base", "The Act base in any year equals the Regulations base one year later, so its benchmarks sit higher", "Only years under the Act alone use the Act base, and every Alpha year is under the Nigeria Tax Act 2025", "Benchmarks from the Nigeria Tax Act, which restart the escalation in 2026, are what the Act base reads"]'::jsonb, 1, 'The benchmark table prints the Act base in any year equal to the Regulations base one year later (in 2026, 56.300000 against 55.200000 for the low benchmark), so between the benchmarks the same price pays a lower royalty by price on the Act base. Condensate pays the royalty by price on both bases, and neither base reads the framework.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 9, 'How is each row of the course''s one-change-at-a-time table on Ekene Alpha built?', '["All eight changes stacked in order, each row a running total of the ones above it", "One year of Alpha per row, changed from then on", "The base less the changed run, so a line that rises under the change prints negative", "One stated change at a time, each line the changed run less the base"]'::jsonb, 3, 'The course sets it out: Ekene Alpha as the base case, then ONE stated change at a time, each run through the engine, and the differences derived as the changed run less the base, line by line. That is why a higher price prints positive (43566660.591831 on royalties) and a prospecting licence negative (-102385291.793528).'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 10, 'Forcing every year of Ekene Alpha to the Act alone moves the hydrocarbon tax by 436533.662718 and companies income tax by 450000.000000. Which provision accounts for those two movements?', '["The two thirds restriction, which the Act alone applies to both tax bases", "Development levy, deducted in both tax bases under the new Act", "The 1 percent of each spend that its fifth year of life leaves unclaimed", "The royalty by price, whose benchmarks the Act alone starts a year earlier"]'::jsonb, 2, 'Alpha spends 120000000 in 2026 and 30000000 in 2027, and each spend reaches its fifth year of life in a year the forced run reads under the Act alone, where the fifth year claims 0.190000 against 0.200000 under the Nigeria Tax Act 2025. The 1 percent left unclaimed raises companies income tax by 450000.000000 at 30 percent, and the hydrocarbon tax by 436533.662718, since that tax takes the allowance at the liquids share. The two thirds restriction limits the companies income tax allowance only, so it cannot reach the hydrocarbon tax; royalties on the row are 0.000000, so the royalty by price did not move; and the levy is charged on the companies income tax assessable profit.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 11, 'Which engine note explains why the additional tax at the fiscal price of PIA s.268 does not appear on any ledger?', '["The daily-rate note, which says the royalty tranches read the year''s crude oil plus condensate over the calendar days of the year and so leave the fiscal price aside", "\"The realised oil and condensate prices stand in for the Commission''s fiscal prices (PIA Seventh Schedule para 8), so the additional tax at the fiscal price (PIA s.268; NTA s.73) is not computed.\"", "Shared-costs note, which says opex, HCDT, NDDC and the capital allowances enter the hydrocarbon tax at the crude-plus-condensate share of gross revenue", "The note on the minimum effective tax rate, which says the top-up is a project-level approximation of NTA s.57 reported on its own line in NTA years"]'::jsonb, 1, 'That is the fiscalPrice note, printed on every PIA ledger. The fiscal oil price and the additional tax at it are concept-only. The daily-rate note is about the royalty tranches, the shared-costs note about cost allocation, and the minimum ETR note about NTA s.57.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 12, 'Which of these is one of the three open readings the course teaches?', '["The hydrocarbon tax rate of a new lease onshore or in shallow water, 15 or 30", "Tertiary education tax of 2.5 percent before 2023, which rests on a secondary source", "NDDC levy base, stated as the total annual budget or as opex alone", "Daily rate, read over calendar days or over the days oil was produced"]'::jsonb, 0, 'The three open readings are the royalty by price base year, the new-lease rate onshore or in shallow water, and the deep offshore rate under the Nigeria Tax Act 2025. The 2.5 percent is a value resting on a secondary source, the NDDC base is a stated alternative, and the daily rate is one of the engine''s declared choices.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 13, 'Where is the edge between an accepted and a refused value of pia_gas_in_country_share_pct?', '["100 is refused, since a share of 100 leaves no exported gas to price at the full rate", "Any share above 50 is refused, since the Regulations cap in-country gas at half", "100 is accepted and returns 0.025000; 100.5 is refused", "Nothing is refused: a share above 100 is capped at 100 with a note in kpis.pia_notes"]'::jsonb, 2, 'The boundary row: "0 and 100 are accepted; above 100 is refused", with 0.025000 at the boundary and a refusal at 100.5. The rate table prints 0.037500 at 50 and 0.035000 at 60, so shares above 50 run, and the engine caps nothing silently: "pia_gas_in_country_share_pct must be a number from 0 to 100; got 100.5."'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 14, 'How many of the provisions this course teaches does the engine compute?', '["14 of 41, with the other 27 taught as concept-only from their citations", "27 of 41, with the other 14 concept-only", "All 41, since every provision the course cites has an engine field behind it", "27 of 41, with the other 14 graded on figures that the lessons derive"]'::jsonb, 1, 'The provision map closes "41 provisions: 27 computed, 14 concept-only." A concept-only provision is taught from its text and never graded on a number, so none of the 14 is graded on a figure of any kind.'),
  ('pia', 'advanced', 'module', 'm05-reading-a-fiscal-outcome', 15, 'Which lines sit on the government side of the engine''s take for a PIA ledger?', '["Only the hydrocarbon tax and companies income tax, the two taxes that charge 30 percent here", "Royalties and every tax, with HCDT and the NDDC levy counted as costs borne by the contractor", "Every tax and royalty except the development levy, which the Service pays into a special account", "Every royalty, HCDT, the NDDC levy and every tax"]'::jsonb, 3, 'The engine''s take is revenue less capex less opex, less the ledger''s net cash flow, over revenue less capex less opex, and every royalty, HCDT, the NDDC levy and every tax is on the government side of that difference. Alpha''s government cash flow is the sum of seven lines, the development levy (35714217.371697) among them.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Across its five years, what does ekene_onshore_across_2026 report as the framework of the whole ledger?', '["kpis.fiscal_framework \"nta_2025\" for the whole ledger, since its last years govern every earlier one", "kpis.fiscal_framework \"pia_only_then_nta_2025\", with kpis.nta_first_year 2026", "kpis.fiscal_framework \"pia_only\" for the whole ledger, since it starts under the Act alone in 2024", "Two framework values, one per Act, and no first NTA year"]'::jsonb, 1, 'A ledger that crosses reports kpis.fiscal_framework "pia_only_then_nta_2025" and kpis.nta_first_year, and the course prints this case with 2026 as its first NTA year. The framework is still read row by row: 2024 and 2025 are "pia_only" and 2026 to 2028 "nta_2025".'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 2, 'The engine flags the two thirds restriction as applying in 2024 and 2025 on ekene_onshore_across_2026. Does it bind?', '["Yes: 2024 claims two thirds of 153422584.102902 and carries the rest of the allowance forward", "It binds in 2025 only, the year the assessable profit falls to 138422805.570953 on lower output", "It binds in 2026, when the carried excess of the two earlier years is claimed in one go", "No: two thirds of each assessable profit is larger than the allowance, so the whole 18000000.000000 is claimed each year"]'::jsonb, 3, 'The course says it plainly: the restriction column is true in 2024 and 2025 and false from 2026, and on this lease it does not bind, because two thirds of each assessable profit is larger than the allowance. The CIT allowance claimed is 18000000.000000 and the amount carried 0.000000 in every year, so nothing is carried into 2026.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Which lines of ekene_onshore_across_2026 read no framework at all?', '["Production royalty on liquids and gas, and the royalty by price", "The tertiary education tax and the development levy, charged on one base", "The capital allowance, whose fifth year is 19 percent under either law", "Companies income tax, charged at 30 percent before and after the switch"]'::jsonb, 0, 'What did not change: the engine''s royalty and royalty by price functions take no framework input. The education tax and the levy turn on the framework of the year, the fifth year of the capital allowance is 19 percent under the Act alone and 20 percent under the Nigeria Tax Act 2025, and companies income tax reads the restriction, which is a framework line.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The 2025 tertiary education tax on ekene_onshore_across_2026 is 4152684.167129. Which text puts that line on the ledger?', '["NTA s.59(1), at 4 percent of the companies income tax assessable profit", "Finance Act 2021, at 2.5 percent, a rate the course takes from a secondary source alone", "Finance Act 2023 s.26, at 3 percent of the companies income tax assessable profit", "PIA s.302, which charges it together with companies income tax at 30 percent"]'::jsonb, 2, '2025 is a year under the Act alone with a TET rate of 3.000000 percent, and the stack cites Finance Act 2023 s.26 for the tertiary education tax on the companies income tax assessable profit. NTA s.59(1) is the development levy of the NTA years, and the 2.5 percent of the Finance Act 2021 applies before 2023.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 5, 'What is the development levy on ekene_onshore_across_2026 in 2027?', '["4364793.688932, at 4 percent of a companies income tax assessable profit of 109119842.223295", "4920525.461957, the levy of the first year under the new Act carried on flat through the ledger", "0.000000, the levy being charged only in the first year of assessment under the new Act", "3852629.452203, at 4 percent of an assessable profit of 109119842.223295 for the year"]'::jsonb, 0, 'Each NTA year pays its own levy on its own profit. For 2027 the ledger row reads 109119842.223295 of assessable profit and 4364793.688932 of levy. The figure 4920525.461957 sits on the 2026 row and 3852629.452203 on the 2028 row, so neither carries over.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 6, 'A ledger crossing into 2026 carries a decommissioning fund contribution in its NTA years. What must its terms state for it to run?', '["The name of the escrow bank, which the engine checks against the Central Bank''s accredited list", "Whether the escrow condition of NTA s.86 is met, as true or false", "Nothing further: the engine deducts a fund contribution in every year whatever its framework", "A deep offshore reading, since a fund contribution is deducted inside the hydrocarbon tax"]'::jsonb, 1, 'The engine refuses an NTA-year fund contribution with no escrow statement: "pia_decom_escrow_condition_met must be true or false: NTA s.86 allows the deduction only when at least 30% of the fund is deposited in an escrow account with a Nigerian bank accredited under the Central Bank of Nigeria''s criteria." The engine takes the condition as a stated fact about the company''s banking; a deep offshore reading is a separate stated input.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 7, 'What does the course prove about every graded field before it grades one?', '["Matching the stdlib oracle''s expected figure stored in the golden file beside the inputs", "Equality at 100 percent working interest and at the working interest the card states", "Rounding to whole US dollars before any comparison with the learner''s figure", "That it is the same under every reading of all three open readings"]'::jsonb, 3, 'The course''s rule for graded numbers: a graded figure is the same under every reading of all three open readings, and each is a return value of this engine on fixed terms and rows. The oracle''s expected figures are provenance and never printed, a graded money figure is at the stated share, and figures are read at six decimals.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 8, 'Where does an Expert learner run the practicals of this course?', '["A spreadsheet the learner builds from the lesson tables, since the course ships no calculator", "The royalty calculator, the one panel the course provides for all three of its tiers", "In the course''s ledger calculator panel, which calls the same vendored engine the lessons quote", "Inside the hydrocarbon tax calculator''s ledger view, which is the only panel the Expert tier is given"]'::jsonb, 2, 'This is an engine course: each tier has a calculator panel that calls the same vendored engine, the royalty calculator at Associate, the hydrocarbon tax calculator at Professional and the ledger calculator at Expert. A learner types or pastes terms and rows, and the panel prints what the engine returns, every refusal and every note.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A case states a working interest of 50 percent. At what level is a money figure from its ledger reported?', '["100 percent, the field level at which the royalty tranches and the allowance cap are read", "At the share: every money line is scaled to the working interest after the field-level arithmetic", "Share for the taxes and field level for royalty, which the operator pays in full on behalf of all partners", "Half the daily rate for the tranches, so the share comes out exact"]'::jsonb, 1, 'Every money figure is at the working interest share: the engine runs the tranches, the allowance cap and every rate at field level and then scales every money line to the share. "at the share" means at the stated working interest, and royalty is a money line like the rest.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 10, 'On ekene_onshore_across_2026, which set of lines turns on the framework of each year?', '["The education tax, the development levy, the capital allowance fifth year and the two thirds restriction", "Royalty by price, whose benchmarks move over to the Act base from 2026 onward", "Hydrocarbon tax rate: 30 percent before 2026 and 15 percent from the switch", "Liquids royalty rate, which the NTA restates with \"bop\" in the place of bopd"]'::jsonb, 0, 'The framework table lists the lines that change with the framework of a year: the tertiary education tax, the development levy, the fifth year of the capital allowance and the restriction (with the deep offshore lines, the escrow condition and the minimum ETR top-up, none of which this onshore case carries). The base year of the royalty by price is a stated input, and a converted onshore lease pays 0.300000 under either framework.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Which pair of notes does ekene_onshore_across_2026 carry because its years fall on both sides of the switch?', '["Minimum ETR approximation note together with the Nigeria Tax Act version note", "Shared-costs note together with the pre-2026 restriction note on capital allowance", "Version note alone, the restriction not binding", "The Nigeria Tax Act version note and the pre-2026 restriction note"]'::jsonb, 3, 'The note conditions: ntaVersion appears for a year under the Nigeria Tax Act 2025, and citRestrictionPre2026 for a year under the Act alone unless the company is in gas operations. This ledger has both kinds of year. The minimum ETR note needs the top-up switched on, the shared-costs note needs gas production, and the restriction note does not ask whether the restriction binds.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Why does a royalty figure on ekene_onshore_across_2026 name its base year?', '["Onshore tranches start in 2021 on the Regulations and in 2020 on the Act, so both royalties move", "Base year sets the framework of each year, and this ledger crosses from the Act into the new Act", "It includes the royalty by price, whose base year is an open reading; the engine default is the Regulations", "The Act''s own example at 75 USD/bbl in 2020 gives different rates on the two bases, 0.025000 on one"]'::jsonb, 2, 'Royalty in this course is the total royalty, the production royalty plus the royalty by price, and a royalty by price is always quoted with its base year: the Act starts the benchmarks in 2020, the Regulations in 2021, and the engine follows the Regulations unless told otherwise. The tranches read no base year, the framework reads the year, and the Act''s example returns 0.025000 on both bases.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which of these figures could a keyed question in this course rest on?', '["The 2026 development levy on ekene_onshore_across_2026, 4920525.461957", "The minimum ETR top-up of 35346403.532609, as the tax a company owes under NTA s.57", "The aggressive_pml_30 hydrocarbon tax of 303622010.869565, as the law for deep offshore", "A petroleum profits tax figure for an oil mining lease that never converted"]'::jsonb, 0, 'Every graded number is a return value of the engine on fixed terms, and the levy is one. The minimum ETR top-up is a labelled approximation and never graded; a deep offshore hydrocarbon tax under the Nigeria Tax Act 2025 is an open reading and never keyed as the law; and a lease that never converted is outside the engine altogether.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What does the course say about the Ekene cases it teaches with?', '["Real Nigerian leases with their names changed, so the figures stay confidential", "Read from the golden file, with the oracle''s expected figures shown beside each of the engine''s own", "Synthetic inputs whose printed figures all come from the stdlib oracle, the course''s independent witness", "Every one is synthetic, read from the golden file''s inputs, with the engine''s own figures printed"]'::jsonb, 3, 'The course states: every Ekene case, field, volume, price and cost is synthetic, written for this platform, read from the vendored golden file''s inputs; the golden also carries the stdlib oracle''s expected figures, which are provenance and never printed, and every figure shown is the engine''s own return on the case inputs.'),
  ('pia', 'advanced', 'module', 'm06-the-expert-reading', 15, 'A reader forces ekene_onshore_across_2026 to "force_pia". How should any figure from that run be quoted?', '["As the ledger''s own figure, since forcing the Act alone changes only the framework labels", "With its override named, since force_pia puts every year on the Act alone, 2026 to 2028 included", "As the law for 2026 to 2028, since the Act alone governed the lease before the switch", "With no qualification, since a forced run matches auto in every year before 2026"]'::jsonb, 1, '"force_pia" puts every year on one framework, so 2026 to 2028 read "pia_only" and pay the tertiary education tax in place of the levy; the course quotes a figure that depends on a setting with that setting. The forced run changes lines as well as labels, and on the course''s Alpha it moves the education tax by 26785663.028773.'),
  ('pia', 'advanced', 'final', null, 1, 'What right does PIA s.70(1)(c) give the holder of a petroleum mining lease?', '["Exploration on a non-exclusive basis for three years, renewable once under the Act''s exploration licence", "To win, work, carry away and dispose of crude oil, condensates and natural gas on an exclusive basis", "Drilling exploration and appraisal wells, with production left to a later mining lease", "Production under its old oil mining lease terms until the conversion date passes"]'::jsonb, 1, 'S.70(1)(c): a petroleum mining lease "may be granted to qualified applicants to: (i) win, work, carry away and dispose of crude oil, condensates and natural gas on an exclusive basis,". Non-exclusive exploration is the petroleum exploration licence of s.70(1)(a), and drilling exploration and appraisal wells is the petroleum prospecting licence of s.70(1)(b).'),
  ('pia', 'advanced', 'final', null, 2, 'For how long may a petroleum mining lease run under PIA s.86(1)?', '["A maximum of 20 years, a term that includes the development period", "Three years, renewable for a further three if the prescribed conditions are met", "Up to 10 years, made of a five-year initial period and a five-year optional extension", "Until 18 months after the effective date, when the lease must be converted again"]'::jsonb, 0, 'S.86(1): a petroleum mining lease "shall be for a maximum period of 20 years, which term shall include the" development period. Three plus three years is the petroleum exploration licence (s.71(3)), and five plus five years is a deep offshore or frontier petroleum prospecting licence (s.77(2)).'),
  ('pia', 'advanced', 'final', null, 3, 'The single-year worked example (2025, a year under the Act alone) is run with pia_tet_rate_pct stated as 2.5. What does the engine do?', '["Refused, since the statutory rate for 2025 is 3 percent and a stated rate may not differ from it", "3 percent applied, the stated rate ignored with no note", "It uses 2.5 for 2025 and names that choice in a note beside the statutory rate", "2.5 used in every year, NTA years included, in place of the levy"]'::jsonb, 2, 'The engine builds one note from the run: "pia_tet_rate_pct 2.5 was used for 2025. The statutory tertiary education tax is 3% from 2023 (Tertiary Education Trust Fund Act s.1(2) as amended by Finance Act 2023 s.26) and 2.5% before; leave pia_tet_rate_pct unset to apply it." A stated rate that differs from the statute is used and named; a year under the Nigeria Tax Act 2025 charges no education tax at all.'),
  ('pia', 'advanced', 'final', null, 4, 'The course reads NTA Seventh Schedule Part IV para 7(3)(c) beside the Act''s own gas royalty. What rates do the two texts print for gas produced onshore?', '["5%, or 2.5% for gas used in-country, in both texts, since the Nigeria Tax Act restates para 10(6) word for word everywhere", "7% onshore in both, since the Nigeria Tax Act replaced the Act''s gas royalty with its own Part IV rates", "2.5% in both, the in-country rate of para 10(6) being applied to all gas that stays in Nigeria", "7% onshore in para 7(3)(c), for leases under NTA Chapter Three Parts II and III; 5%, or 2.5% for gas used in-country, in para 10(6)"]'::jsonb, 3, 'The Nigeria Tax Act prints, for leases under its Chapter Three Parts II and III, a gas royalty of "(i) onshore areas: 7 %, and (ii) offshore areas: 5%;", and the course reads it beside the Act''s own gas royalty, 5 percent and 2.5 percent in-country (PIA Seventh Schedule para 10(6); NTA Seventh Schedule para 6(2)(f)). The engine computes only the Act''s rates; para 7(3)(c) belongs to the concept-only terms of leases outside the conversion.'),
  ('pia', 'advanced', 'final', null, 5, 'Para 14(4) of the PIA Seventh Schedule sets a minimum government share of profit oil by cumulative production per field. What does it print for the first and last bands?', '["10% up to and including 50 million barrels, and 35% over 1500 million barrels", "5% up to and including 100 million barrels, and 25% over 750 million barrels as printed", "70% up to and including 50 million barrels, and 60% after conversion", "5% up to and including 50 million barrels, and 45% over 1500 million barrels"]'::jsonb, 3, 'Para 14(4)(a) prints "(a) up to and including 50 million barrels - 5% ;" and para 14(4)(f) "(f ) over 1500 million barrels: 45%." 10, 15, 25 and 35 percent are the middle bands, and 70 and 60 percent are the cost limits of para 14(4) and 14(9). Production sharing under the Act is concept-only.'),
  ('pia', 'advanced', 'final', null, 6, 'When an oil prospecting licence converts, what does PIA s.93(7)(b) make of the areas selected under s.93(1)(d) and (e)?', '["Petroleum prospecting licences, with fiscal terms under s.267(b) for appraisal and discovery work on the retained areas", "Petroleum mining leases, with fiscal terms under s.267(a) and the other terms of Chapter 4", "Relinquished areas, handed back because an oil prospecting licence cannot hold production", "Marginal fields under s.94(1), on the original royalty rates and farm-out agreements"]'::jsonb, 1, 'S.93(7)(b): areas "selected under section 93 (1) (d) and (e) of this Act shall be converted into petroleum mining leases with fiscal terms as applicable under section 267 (a) and other terms of Chapter 4 of this Act,". The areas designated under s.93(1)(a), (b) and (c) continue as a prospecting licence under s.93(7)(a), and s.94(9) allows no new marginal fields.'),
  ('pia', 'advanced', 'final', null, 7, 'Which enactments does NTA s.196(c) and (d) list among those it repeals?', '["The Companies Income Tax Act and the Deep Offshore and Inland Basin Act", "Petroleum Industry Act 2021 in full, with its royalty Schedule and its conversion rules", "Tertiary Education Trust Fund Act 2011 in full, since the levy takes over its funding", "Finance Act 2023 and the Petroleum Royalty Regulations 2022 made under the PIA"]'::jsonb, 0, 'S.196(c) and (d) read "(c) Companies Income Tax Act, Cap. C21, Laws of the Federation of Nigeria, 2004; (d) Deep offshore and Inland Basin Act, Cap. D3, Laws of the Federation". The Petroleum Industry Act loses listed Parts and Schedules under s.197(1), and s.197(5) deletes only sections 1, 2 and 3(3) of the Tertiary Education Trust Fund Act.'),
  ('pia', 'advanced', 'final', null, 8, 'At what rates does NTA s.56 charge company income tax?', '["30 per cent for every company, small or not, from the commencement of the Act", "0% for a small company and 30 per cent for any other company from the Act''s commencement", "15 per cent for a small company and 30 per cent for any other company", "4% for a small company, the same rate as the development levy, and 30 per cent for the rest"]'::jsonb, 1, 'S.56: "(a) a small company, at 0%; and (b) any other company, at the rate of 30 per cent from the commence- ment of this Act." 15 percent is the minimum effective tax rate of s.57, and the development levy of 4 percent excludes small companies altogether under s.59(1).'),
  ('pia', 'advanced', 'final', null, 9, 'The case ekene_force_pia_2027 covers 2027 to 2032 under the override force_pia. Which tertiary education tax rate and which development levy does its ledger print?', '["An education tax of 0.000000 and a levy at 4 percent, since 2027 onward are years under the Nigeria Tax Act 2025", "A tertiary education tax rate of 3.000000 percent and a levy of 0.000000, since force_pia makes every year a year under the Act alone", "An education tax rate of 2.500000 percent, since a forced year falls back to the rate before 2023", "Both lines charged at once, since a forced ledger keeps the new Act''s levy beside the education tax"]'::jsonb, 1, 'The course prints this case: every year reports "pia_only", the tertiary education tax rate is 3.000000 percent and the development levy is 0.000000. "force_pia" puts every year on one framework, and a year under the Act alone charges the education tax (3 percent from 2023) and no levy.'),
  ('pia', 'advanced', 'final', null, 10, 'How do the two Acts treat the last 1 percent of a qualifying capital spend?', '["Both Acts claim it in the fifth year, so that the full 100 percent is written off within the ledger", "The PIA claims it in a sixth year of life; the NTA adds it to the fifth year, so the fifth year claims more than 20 percent", "Both Acts retain it until disposal, which is why the fifth year claims 19 percent under either law", "The PIA retains it in the books until disposal; the NTA records it as a notional amount that changes no claim"]'::jsonb, 3, 'PIA Fifth Schedule para 5(2) retains "1% of the initial cost of the asset which may only be written off in accordance with subparagraph (3)", and NTA First Schedule Part II para 4(2) records 1% "for statistical purposes until the asset is disposed" as "a notional amount" that "shall not increase or reduce the amount of capital allowance claimable under this Part." The NTA fifth year is 20 percent (0.200000) and the PIA fifth year 19 percent (0.190000).'),
  ('pia', 'advanced', 'final', null, 11, 'In 2025 the Ekene deep offshore lease has an HCT chargeable profit of 795646660.199557. What do its hydrocarbon tax and companies income tax lines show?', '["Hydrocarbon tax at 30 percent of 795646660.199557, since s.260(3) names frontier acreage alone", "Both 0.000000, since deep offshore sits outside the Act''s fiscal Part altogether in 2025", "Hydrocarbon tax under the stated reading, since every year of this ledger needs one", "Hydrocarbon tax 0.000000 and companies income tax 291253998.059867 on the whole profit"]'::jsonb, 3, 'The 2025 row, a year under the Act alone: HCT 0.000000 and CIT 291253998.059867. The lease has a chargeable profit and pays no hydrocarbon tax, because PIA s.260(3) keeps deep offshore outside the tax, and companies income tax is charged on the whole profit. The stated reading matters only in years under the Nigeria Tax Act 2025.'),
  ('pia', 'advanced', 'final', null, 12, 'Take the deep offshore case into 2027 under the custom reading, with pia_deep_offshore_hct_custom_rate_pct stated as 20. Which 2027 figure does the engine print on the tax line?', '["304277502.330847, the figure that the course calls the law for deep offshore from 2026", "0.000000, since any custom reading below 30 is read by the engine as conservative_zero", "202851668.220565, quoted with the custom 20 reading beside the other two", "202414673.913043, the same figure in every year from 2026, the rate and profit both fixed"]'::jsonb, 2, 'For 2027 the custom 20 column reads 202851668.220565, beside 304277502.330847 for aggressive_pml_30 and 0.000000 for conservative_zero, on a chargeable profit of 1,014,258,341.102824. 202414673.913043 belongs to 2026, whose profit differs. Each is quoted with its reading, and none is the law.'),
  ('pia', 'advanced', 'final', null, 13, 'What do the texts and the engine give frontier acreage (ekene_frontier, 120 USD/bbl, 2026)?', '["A royalty rate of 0.075000, no royalty by price and no hydrocarbon tax under either framework", "The shallow water tranches at 0.050000 and 0.062500, with royalty by price at the high benchmark", "A royalty rate of 0.075000 with a royalty by price of 10 percent above the high benchmark", "No royalty until the acreage is reclassified, and hydrocarbon tax at 30 percent from 2026"]'::jsonb, 0, 'The frontier case returns a liquids royalty rate of 0.075000 and a royalty by price of 0.000000 (PIA Seventh Schedule para 11(2)). The rate table gives frontier 0.000000 hydrocarbon tax under either framework: PIA s.260(3) and NTA s.65(4) keep frontier acreage out of the tax "until it is reclassified".'),
  ('pia', 'advanced', 'final', null, 14, 'Which two values in this course rest on secondary sources, and how does the course treat them?', '["The tertiary education tax of 2.5 percent before 2023 and the NDDC levy base of the total annual budget, each said to be so where used", "Effective date of the Petroleum Industry Act and the escrow condition of NTA s.86, both left as stated inputs", "Royalty by price base year and the deep offshore rate, both of which are taught as open readings", "Two thirds restriction and the 3 percent education tax, both kept as hidden defaults"]'::jsonb, 0, 'The editions table lists the Finance Act 2021 (2.5 percent) and the NDDC Act 2000 s.14(2)(b) (3 percent of the total annual budget) as secondary, and the course states that a secondary source is never a hidden default. The 3 percent rate rests on the Finance Act 2023 (s.26), read as a scan, and the open readings are a separate matter.'),
  ('pia', 'advanced', 'final', null, 15, 'How does the engine''s daily rate for the royalty tranches differ from the Regulations'' own method?', '["Crude oil alone over 365 days in every year, leap years included, leaving condensate out of the daily rate the tranches read", "It divides the year''s crude oil plus condensate by the calendar days; the Regulations divide each month''s production by the days oil was produced", "Each month''s production over the days oil was produced in that month, as r.12(2) directs, then averaged over the twelve months of the year", "The stated peak daily rate of the year, since the tranches of para 10 are set per day and a year''s peak decides its band"]'::jsonb, 1, 'The engine''s note: "Royalty tranches read the year''s crude oil plus condensate divided by the calendar days of the year; the Regulations (r.12(2)) divide each month''s production by the days oil was produced in that month." Condensate counts in the daily rate, and 2024 and 2028 have 366 calendar days.'),
  ('pia', 'advanced', 'final', null, 16, 'The Regulations'' Schedule prints the middle royalty by price benchmark as 102.00, 104.00, 106.00, 108.00 and 110.00 for 2022 to 2026. What does the engine do?', '["The printed column is used as the law, since a Schedule''s table outranks its own written words", "An average of the printed figure and the escalated one each year, with no note", "Refusal of any ledger that reaches 2023 until a middle benchmark is stated", "It applies the Schedule''s own 2 percent rule and says so in a note, giving 104.04 in 2023"]'::jsonb, 3, 'The engine''s note: "The Regulations'' benchmark table prints the 100 USD level as 102.00, 104.00, 106.00, 108.00 and 110.00 for 2022 to 2026, which does not follow its own 2% rule; the engine applies the rule (104.04 in 2023)." The benchmark table prints 104.040000 for 2023 on the Regulations base, and the course names the misprint as it quotes it.'),
  ('pia', 'advanced', 'final', null, 17, 'The Act''s own example puts the royalty by price at 2.5 percent at 75 USD/bbl in 2020. What does the engine return, and on which base?', '["0.025000 on the Act base and 0.019290 on the Regulations base, the base year alone moving the rate between the two", "0.025000 on the Act base and also 0.025000 on the Regulations base, which keeps the 2021 levels for 2020", "0.017935 on both bases, since the benchmarks escalate from 2020 on either reading of the Act and the Regulations", "0.025000 on the Act base only, as the Regulations base refuses a year before 2021"]'::jsonb, 1, 'The course prints the example: the engine on the Act base returns 0.025000 at 75 USD/bbl in 2020, and on the Regulations base, which keeps the 2021 levels for 2020, also 0.025000. 0.019290 is the Regulations-base rate at 75 USD/bbl in 2025, and 0.017935 the Act-base rate in that year.'),
  ('pia', 'advanced', 'final', null, 18, 'On the NTA decommissioning fund cases, what is the 2026 hydrocarbon tax with the escrow condition met and not met?', '["28569497.282609 in both runs, the escrow condition reaching companies income tax alone", "28569497.282609 met and 31569497.282609 not met", "31569497.282609 met and 28569497.282609 not met, the deduction adding to the tax", "30069497.282609 met and 33069497.282609 not met, the same pair as the income tax"]'::jsonb, 1, 'The escrow table prints 2026 HCT 28569497.282609 (met) and 31569497.282609 (not met); companies income tax is 30069497.282609 and 33069497.282609. A deductible contribution sits inside the cost price ratio for the hydrocarbon tax and is deducted in full for companies income tax, so both taxes move when the condition is not met.'),
  ('pia', 'advanced', 'final', null, 19, 'With the escrow condition unmet, what leaves the company in 2027 as a fund payment, and what reaches the tax lines?', '["No contribution and no deduction, the fund being paused until the condition is met", "A contribution of 10000000.000000 and a deduction of 10000000.000000 carried to 2028", "A contribution of 0.000000, since only the tax treatment follows an unmet condition", "A contribution of 10000000.000000 and a deduction of 0.000000"]'::jsonb, 3, 'Payment and relief part company here. In 2027 the fund still receives 10000000.000000 whether or not the bank test is passed; with the test failed, the deduction column reads 0.000000, and the course says the cash goes out either way. No carry into 2028 appears on the rows.'),
  ('pia', 'advanced', 'final', null, 20, 'How does NTA s.57(4) define the "profits" that the minimum effective tax rate test divides by?', '["The companies income tax assessable profit of each project, as the engine''s top-up line reads it in NTA years", "Gross revenue less royalties, the base the hydrocarbon tax charges before its capital and production allowances", "Taxable profits after capital allowances, as the Service assesses them each year", "Net profits before tax in the audited financial statement, less 5% of depreciation and personnel cost"]'::jsonb, 3, 'S.57(4): ""profits" means the net profits before tax as reported in the audited financial statement less 5% of depreciation and personnel cost for the year." The engine''s top-up is a labelled project-level approximation on the companies income tax assessable profit, which is why the test itself is concept-only.'),
  ('pia', 'advanced', 'final', null, 21, 'To which companies does the minimum effective tax rate of NTA s.57 apply?', '["Every company in upstream petroleum operations, whatever its size or its ownership", "A constituent entity of an MNE group, and any other company with aggregate turnover of N20,000,000,000 or more", "Small companies only, since larger companies pay the 30 per cent rate of s.56(b)", "Only companies paying hydrocarbon tax, whose effective rate is tested field by field"]'::jsonb, 1, 'S.57(2): "The provisions of this section shall apply to: (a) a company that is a constituent entity of an MNE group; and (b) any other company with an aggregate turnover of N20,000,000,000 and above in the relevant year of assessment." The test is on the company, which is why the engine''s project top-up is an approximation.'),
  ('pia', 'advanced', 'final', null, 22, 'Ekene Alpha''s oil price is raised to 95 USD/bbl on the Regulations base. Which provision totals move?', '["Royalties alone, by 43566660.591831, the higher price reaching no line that comes after the royalty", "The taxes alone, the royalty by price staying fixed at its 2026 benchmark for every year", "Royalties, hydrocarbon tax, companies income tax and the levy all rise, with TET at 0.000000", "Every line including TET, which rises by 9768447.976327 on the larger profit"]'::jsonb, 2, 'The one-change row prints royalties 43566660.591831, hydrocarbon tax 72668690.783886, companies income tax 73263359.822451, TET 0.000000, levy 9768447.976327 and take 0.685923. The price moves the royalty by price and everything after it; Alpha has no year under the Act alone, so the education tax cannot move, and 9768447.976327 is the levy.'),
  ('pia', 'advanced', 'final', null, 23, 'Under r.16 of the Regulations, how is marketable gas used in Nigeria charged, set beside gas that is exported?', '["5% for both, the in-country rate of the Act being left out of the Regulations altogether", "2.5% for both, since export gas is also produced and utilised in-country before it is shipped", "2.5% for gas used in Nigeria under r.16(1)(a), and 5% for gas exported under r.16(5)", "7% onshore and 5% offshore for both, as for leases outside the Act"]'::jsonb, 2, 'R.16(1)(a): "(a) the applicable rate shall be 2.5% pursuant to paragraph 10(6) of the" Seventh Schedule; r.16(5): "(5) The royalty based on production of natural gas for export shall be at a rate of 5% of the chargeable volumes". The engine blends the two by the stated in-country share.'),
  ('pia', 'advanced', 'final', null, 24, 'Under PIA s.272(2), across what may a company consolidate costs and taxes for the hydrocarbon tax?', '["Every field it operates, whoever holds the licence, as for companies income tax", "Only across assets in which it holds licences and leases", "Terrains, but only after the Commission has certified the consolidation each year", "Across fields within one terrain, with onshore and shallow water kept apart"]'::jsonb, 1, 'S.272(2): a company "shall be allowed to consolidate costs and taxes for the purposes of hydrocarbon tax only across assets in which it holds licences and leases", and NTA s.76(2) restates it. The engine does not model consolidation: it is concept-only.'),
  ('pia', 'advanced', 'final', null, 25, 'What does PIA s.265(4) allow a company to do with a loss deduction?', '["Carry it back to the previous accounting period and reclaim hydrocarbon tax already paid for that period", "Transfer it to companies income tax when the hydrocarbon tax loss pool cannot use it in the next year", "Elect in writing to defer all or part of it to the next accounting period, and elect again later", "Nothing more than use it in the first period after the loss, since s.265(3) is exhaustive"]'::jsonb, 2, 'S.265(4): "the company may elect in writing that a deduction or any part to be made under this section shall be deferred to and be made in the succeeding accounting period, and may so elect in any succeeding accounting period." The election is concept-only; the engine keeps the two loss pools apart and uses a loss in the next year.'),
  ('pia', 'advanced', 'final', null, 26, 'What is the fiscal oil price of PIA Seventh Schedule para 8?', '["A price the Commission sets for each field at the measurement points, an export parity price net of transport in Nigeria", "The realised price the company sells at, which the engine reads directly from the stated terms", "The high royalty by price benchmark of the year, escalated by 2 percent every 1 January", "A price the Service assesses after the year ends from the company''s audited statements"]'::jsonb, 0, 'Para 8(1): the royalties "shall be based on the fiscal oil price determined for the field at the measurement points under applicable regulations or guidelines, and this price shall be determined by the Commission"; para 8(2): it "shall be an export parity price taking into consideration the deduction of transportation costs within Nigeria". The engine''s note says the realised prices stand in for it.'),
  ('pia', 'advanced', 'final', null, 27, 'What does the additional tax of PIA s.268 compare a company''s chargeable tax with?', '["The tax that would be due if every barrel it sold that year were priced at the royalty by price high benchmark", "NTA s.57''s 15% minimum effective tax rate on its audited profit before tax", "The tax due if its exported crude were valued at barrels at the measurement point times the fiscal oil price", "What a converted lease would pay on the same profit at the 30 percent class of s.267(a), whatever the lease''s own class"]'::jsonb, 2, 'S.268(2) makes the comparison amount the tax that would be due if the proceeds of sale were "the amount obtained by multiplying the number of barrels of that crude oil determined at the measurement point by the fiscal oil price per barrel." NTA s.73 restates it. The engine does not compute it, as its fiscal price note says.'),
  ('pia', 'advanced', 'final', null, 28, 'How do the Petroleum Royalty Regulations 2022 work out the royalty rate of a field lying partly onshore and partly in shallow water?', '["Charge the whole field at the onshore rate, the higher of the two terrain rates above 10,000 bopd, since para 10(7) favours the Federation", "Charge it at the shallow water rate, since the engine reads the water depth of each well and the deeper wells decide the terrain of the field", "Compute the rate as if the whole field were onshore and as if it were all in shallow water, then weight the two by each terrain''s share", "Split the field into two ledgers, one per terrain, and apply each terrain''s tranches to that part''s own daily rate alone"]'::jsonb, 2, 'R.14(5) opens "(5) The weighted average royalty rate calculation for a field partially in onshore and partially in shallow water shall be as follows: (a) determine the royalty rate as if the entire field is onshore ;", and the course''s paraphrase completes the method with the shallow water rate and each terrain''s share of production. The engine takes one terrain string and never reads the water depth, so this is concept-only.'),
  ('pia', 'advanced', 'final', null, 29, 'How does PIA Fifth Schedule para 17(2) treat exploration spending and the first two appraisal wells in a field?', '["Qualifying capital expenditure, written off at 20% a year for four years and at 19% in the fifth year of life", "Costs that sit outside the cost price ratio limit, deducted in full in the year incurred like royalties and HCDT", "As deductible costs, 100% in the year incurred; further pre-production exploration and appraisal is amortised", "As an acquisition cost, claimed only when the field starts commercial production"]'::jsonb, 2, 'Para 17(2): "Exploration expenditure and the first two appraisal wells expenditure in the same field are to be treated as deductible costs 100% in the year incurred, while for additional exploration expenditures and appraisal expenditures in the same field relating to pre-production period are to be amortised". The engine does not compute it: exploration expensing is concept-only.'),
  ('pia', 'advanced', 'final', null, 30, 'Who administers royalty under the Nigeria Tax Act 2025, set beside the Petroleum Industry Act 2021?', '["The Service under the Nigeria Tax Act, where the Act gave the Commission the determination and collection of royalties", "Commission under both Acts, since the Nigeria Tax Act does not touch the administration of royalty at all in its text", "Nigerian Sovereign Investment Authority under both Acts, since it is credited with royalty by price", "Authority for midstream royalty and the Service for upstream royalty, split between the two bodies by the Nigeria Tax Act"]'::jsonb, 0, 'PIA s.259(b)(i) gives the Commission the determination and collection of royalties; under the Nigeria Tax Act the Service administers royalty (NTA s.89(2) and Seventh Schedule para 1(1)). Royalty by price is credited to the Nigerian Sovereign Investment Authority, which does not administer it.'),
  ('pia', 'advanced', 'final', null, 31, 'Where does the development levy of NTA s.59 go, and which profits does s.59(4) keep it off?', '["Into a special account, shared by fixed percentages with half to the Tertiary Education Trust Fund; s.59(4) keeps it off profits computed for hydrocarbon tax", "Into the Federation Account with every other petroleum revenue under PIA s.258(2), charged on the hydrocarbon tax profit as well as on the income tax base", "Wholly to the Tertiary Education Trust Fund, as the education tax went, and charged on the hydrocarbon tax assessable profit of the year", "Into the Nigerian Sovereign Investment Authority beside the royalty by price, charged at 4 percent of gross revenue less royalties"]'::jsonb, 0, 'The Service collects the levy into a special account (s.59(2)) and shares it by fixed percentages, 50 percent to the Tertiary Education Trust Fund (s.59(3)), and s.59(4) keeps it off assessable profits computed for hydrocarbon tax. The engine charges it on the companies income tax assessable profit in years under the Nigeria Tax Act 2025.'),
  ('pia', 'advanced', 'final', null, 32, 'Which paragraph of the PIA''s production sharing Part does NTA s.197(1)(d) delete?', '["Paragraph 14 (4), taking the 70% cost limit for new acreage with it", "Paragraph 14 (6) of Part IV of the Seventh Schedule", "Paragraph 14 (9), taking the 60% cost limit for converted contracts with it", "The whole of Part IV, so that no production sharing terms survive the Act"]'::jsonb, 1, 'S.197(1)(d) reads "(d) paragraph 14 (6) of Part IV of the Seventh Schedule." The course does not print para 14(6), so it teaches only that the deletion exists; the cost limits of para 14(4) and 14(9) are quoted as the Act prints them.'),
  ('pia', 'advanced', 'final', null, 33, 'A holder never signs a conversion contract. What do PIA s.303(1) and NTA s.87(1) say, read together?', '["The NTA hydrocarbon tax Part applies to it from 2026, whatever its conversion status or the terms of its old lease", "The Act applies to it from the conversion date, on the 15 percent class of s.267(b) for its producing areas", "It must relinquish its lease under s.93(4) once the 18-month window has closed", "The Act and the NTA hydrocarbon tax Part do not apply to it until its licence or lease ends or expires"]'::jsonb, 3, 'S.303(1) keeps the Act away from holders "who do not enter into a conversion" contract, and NTA s.87(1) says the NTA hydrocarbon tax Part and the PIA do "not apply to holders of an oil prospecting licence or oil mining lease who do not" convert, until the licence or lease ends or expires. The Nigeria Tax Act carries petroleum profits tax for such leases in its own Part. All of it is concept-only.'),
  ('pia', 'advanced', 'final', null, 34, 'A producing marginal field converted under s.94(1) runs across 1 January 2026. What hydrocarbon tax rate does the engine apply in its NTA years?', '["0.300000 from 2026, the Nigeria Tax Act having no marginal field class of its own", "0.000000 from 2026, since NTA s.65(1) names only onshore, shallow water and deep offshore", "A stated rate of 15 or 30, since a marginal field in NTA years is an open reading", "0.150000, the same as in its years under the Act alone"]'::jsonb, 3, 'The rate table gives a flagged shallow water field 0.150000 under "either" framework (PIA s.94(1) with s.267(b)), and the hydrocarbon tax rates onshore and in shallow water carry across unchanged in NTA s.72. The new-lease rate is the open reading onshore and in shallow water, and a marginal field is a converted lease.'),
  ('pia', 'advanced', 'final', null, 35, 'What does NTA Sixth Schedule para 2(1) keep of the cost price ratio?', '["Only in years under the Act alone, a 65% limit lifted for years under the Nigeria Tax Act 2025", "65% that now also caps royalties, HCDT and the NDDC levy within the same cost pool", "The limit of 65% of gross revenues determined at the measurement points, rents, royalties and like contributions left outside", "A limit of 70% based on total oil production, as for a contract on new acreage"]'::jsonb, 2, 'NTA Sixth Schedule para 2(1) prints "a cost price ratio limit of 65% of gross revenues determined at the measurement points.", excluding the costs related to s.263(1)(a), (b) and (h). The engine''s cost price ratio reads no framework, and royalties, HCDT and the NDDC levy sit outside the cap. 70% is a production sharing cost limit.'),
  ('pia', 'advanced', 'final', null, 36, 'A ledger states pia_capex_recovery_years as 4. What does the engine say?', '["\"pia_capex_recovery_years is 4, but the PIA Fifth Schedule para 17(1) and NTA First Schedule Part II para 14(1) fix the capital allowance at five years (20, 20, 20, 20, 19 percent under the PIA; 20 percent a year under the NTA).\"", "It runs a four-year schedule at 25 percent a year and adds a note to kpis.pia_notes naming the stated life beside the statutory five years, as it does for a stated tertiary education tax rate", "It applies five years in years under the Nigeria Tax Act 2025, where the First Schedule fixes the life, and the stated four years in every year under the Act alone", "A refusal only for a ledger that reaches a year under the Nigeria Tax Act 2025, where 20 percent a year is fixed; a ledger wholly under the Act alone runs on the stated four years"]'::jsonb, 0, 'That is the first sentence of the engine''s refusal: the capital allowance life is fixed by the texts at five years, so any other life is refused. The five-year schedule is 0.200000 in years 0 to 3 under both laws and 0.190000 or 0.200000 in the fifth year by the law of the year.'),
  ('pia', 'advanced', 'final', null, 37, 'A ledger states pia_hct_rate_override_pct as 150. What comes back?', '["Capped at 100 percent, with a note in kpis.pia_notes about the cap it applied", "150 percent, since an override replaces the rate with no check", "30 percent, the override ignored above 100", "It is refused, the engine accepting an override only within 0 to 100"]'::jsonb, 3, 'The engine''s words: "pia_hct_rate_override_pct must be a number from 0 to 100; got 150." A refusal is a thrown error and returns no ledger, so there is no silent cap, no silent pass-through and no silent fallback to the statutory rate.'),
  ('pia', 'advanced', 'final', null, 38, 'A ledger states pia_price_royalty_base as "act_2021". What happens?', '["It is refused: the base must be \"regulations_2021\" or \"act_2020\"", "Runs on the Act''s reading, since the Act''s benchmarks begin in 2021", "Falls back to the Regulations base, the engine''s default for an unknown value", "Royalty by price is switched off for every year of the ledger it runs"]'::jsonb, 0, 'The engine''s message: "pia_price_royalty_base must be "regulations_2021" or "act_2020"; got "act_2021"." The Act starts the benchmarks in 2020 ("act_2020"), the Regulations in 2021 ("regulations_2021"), and the base year is an open reading the learner states.'),
  ('pia', 'advanced', 'final', null, 39, 'Which provisions does the course cite for doing the fiscal arithmetic at field level and scaling money to the working interest?', '["PIA s.273(4) and NTA s.77(4)", "PIA s.302(5) and NTA s.78(3)(a), which keep the two taxes apart", "PIA s.265(2) and NTA s.70(2), which split assessable profit by class", "PIA s.272 and NTA s.76, the consolidation provisions across terrains"]'::jsonb, 0, 'The provision map lists "Working interest: fiscal arithmetic at field level, money at the share" under PIA s.273(4) and NTA s.77(4). S.302(5) and s.78(3)(a) make the hydrocarbon tax non-deductible for income tax, s.265(2) and s.70(2) separate the two tax classes, and s.272 and s.76 are consolidation.'),
  ('pia', 'advanced', 'final', null, 40, 'What does the engine''s note on the pre-2026 restriction say about years before 1 May 2023?', '["The restriction did not exist before 1 May 2023, so those earlier years claim the whole capital allowance in full", "Those years are refused until a restriction is stated, since the missing wording is one of the open readings", "The wording then in force was not read, and the engine applies the same restriction to every year before 2026", "The restriction was one half before 1 May 2023, a figure taken from a secondary source"]'::jsonb, 2, 'The note: "The wording in force before 1 May 2023 was not read; the engine applies the same restriction to every year before 2026." The course''s three open readings do not include it, nothing is refused on it, and the course prints no other fraction for those years.'),
  ('pia', 'advanced', 'final', null, 41, 'On ekene_cpr_binding_forfeiture, 93000000.000000 of cost is still carried when the ledger ends. Which tax loses that cost, and what does the other tax do with opex?', '["The hydrocarbon tax forfeits it; companies income tax deducts opex in full, the cap never reaching it", "Both taxes forfeit it, since the cost price ratio caps the companies income tax base in the same way", "Companies income tax forfeits it, and the hydrocarbon tax deducts it in a final year", "Neither tax loses it, since the carry is claimed against the next lease''s revenue"]'::jsonb, 0, 'The cost still carried at the end, 93000000.000000, is reported as cpr_forfeited_at_cessation. PIA Sixth Schedule para 2(2)(c) makes such costs not deductible for the hydrocarbon tax, and the cap limits the hydrocarbon tax only: companies income tax deducts opex in full (40000000.000000 in each year of the case).'),
  ('pia', 'advanced', 'final', null, 42, 'The new onshore lease ekene_onshore_new_cap_crossing is run at a stated 15 and at a stated 30. Which 2026 figures stay the same?', '["The hydrocarbon tax, 22711732.336957, since the rate only reaches the chargeable profit", "The HCT chargeable profit, 151411548.913043, and companies income tax, 50223464.673913", "Nothing at all, since the stated rate reaches every line through the tax base", "Companies income tax alone, the chargeable profit rising at the higher stated rate"]'::jsonb, 1, 'The two-rate table prints 2026 HCT chargeable profit 151411548.913043 under both, hydrocarbon tax 22711732.336957 at 15 and 45423464.673913 at 30, and companies income tax 50223464.673913 under both. The stated rate moves the hydrocarbon tax line alone, because companies income tax does not deduct it; the rate of such a lease is an open reading.');
